// THE LONG KNIVES — persistent world engine for AI Dungeon
// Design goals: relationships with memory, autonomous NPC goals, offscreen world motion,
// slow-burn twists, promises/debts, influence, continuity prompts and spoiler-safe status.
// Uses documented AI Dungeon surfaces only: state, history, storyCards, info,
// state.memory.frontMemory, updateStoryCard and log.

const LK_VERSION = "3.1";

const LK_DEFAULTS = {
  enabled: true,
  relationships: true,
  livingWorld: true,
  npcGoals: true,
  twists: true,
  visibleUpdates: true,
  updateEvery: 6,
  twistSeedSpacing: 6,
  twistGrowAfter: 5,
  twistComplicateAfter: 6,
  twistRipeAfter: 7,
  twistFalloutTurns: 5,
  maxActiveTwists: 4,
  pressureRate: 1,
  frontMemoryMax: 3200,
  debug: false,
  innerLives: true,
  profileAuthority: true,
  matureTone: true,
  statusCard: true,
  intensity: 2,
  twistPace: 6,
  maxTwists: 5,
  memoryDepth: 10
};

const LK_DIMENSIONS = [
  "trust", "loyalty", "respect", "fear",
  "resentment", "affection", "obligation", "suspicion",
  "attraction", "rivalry", "jealousy", "dependence"
];

const LK_PRESSURE_LABELS = {
  familyStrain: "family",
  rivalPressure: "rival",
  legalScrutiny: "law",
  businessStress: "business",
  publicExposure: "public",
  internalCompetition: "internal"
};

const LK_TWIST_BLUEPRINTS = [
  {kind:"protective-secret", truth:"A withheld fact was kept back to protect somebody, not to betray the family."},
  {kind:"divided-loyalty", truth:"A genuinely loyal person also has a second obligation that sometimes conflicts with the family."},
  {kind:"old-debt", truth:"A present-day decision is being shaped by an old favour or debt that has not previously looked important."},
  {kind:"financial", truth:"What looks like personal treachery is partly driven by a legitimate financial or contractual pressure."},
  {kind:"misread-evidence", truth:"A witness or document is basically genuine, but the obvious interpretation of it is wrong."},
  {kind:"succession", truth:"A move that appears operational is really changing leverage in the future succession struggle."},
  {kind:"private-alliance", truth:"Two people on different sides have a narrow private understanding without being full allies."},
  {kind:"relationship", truth:"A personal relationship explains behaviour that has been mistaken for pure business strategy."},
  {kind:"cover-story", truth:"Someone accepted a damaging version of events because the alternative would expose another person."},
  {kind:"law-pressure", truth:"Legal or regulatory pressure is changing someone's choices before anybody publicly admits the pressure exists."},
  {kind:"internal-split", truth:"A faction that appears united is privately divided over how far to escalate."},
  {kind:"third-party", truth:"A conflict between two obvious sides is being exploited by a third party with a narrower objective."},
  {kind:"ambition", truth:"An ally's ambition is making them a political rival without making their past loyalty fake."},
  {kind:"mistake", truth:"An important suspicious event began as an ordinary human mistake and became dangerous because people concealed it."},
  {kind:"inheritance", truth:"An old family arrangement or promise changes who actually benefits from the current power struggle."},
  {kind:"provocation", truth:"A visible incident was designed mainly to provoke a predictable reaction rather than achieve its apparent goal."},
  {kind:"ethical-limit", truth:"A professional ally has reached a private ethical limit and is preparing to withdraw rather than openly betray anyone."},
  {kind:"sincere-reconciliation", truth:"A reconciliation is sincere even though one participant is still hiding a separate problem."}
];

const LK_CUE_SETS = {
  trustUp: ["thank you","thanks","kept your word","kept my word","you were right","i believe you","trust you","trusted you","honest with me","told me the truth"],
  trustDown: ["lied to","lie to","betrayed","betray me","betray you","set me up","set you up","deceived","kept that from me","hid this from me"],
  loyaltyUp: ["stood by","stand by","backed me","back you","stayed with","wouldn't leave","would not leave","took my side","covered for"],
  loyaltyDown: ["abandoned","sold me out","sold you out","changed sides","walked out on","turned on me","turned on you"],
  respectUp: ["good work","well done","impressive","competent","handled that","smart move","you did well","respect you"],
  respectDown: ["idiot","useless","pathetic","incompetent","coward","failure","embarrassment"],
  fearUp: ["threatened","threaten you","threaten me","afraid of","scared of","terrified of","gun to","knife to"],
  resentmentUp: ["humiliated","humiliate","insulted","insult you","insult me","embarrassed me","embarrassed you","never forgive"],
  affectionUp: ["care about you","care about me","love you","loves you","kissed","hugged","missed you","worried about you","proud of you"],
  obligationUp: ["owe you","owe me","favour","favor","debt to you","debt to me","did me a favour","did me a favor"],
  apology: ["i'm sorry","i am sorry","apologise","apologize","apology"],
  promise: ["i promise","i swear","you have my word","my word on it","i give you my word"]
};

function lkClamp(n, lo, hi) { return Math.max(lo, Math.min(hi, Number(n) || 0)); }
function lkNum(v, d) { const n = Number(v); return Number.isFinite(n) ? n : d; }
function lkBool(v, d) {
  if (typeof v === "boolean") return v;
  if (v == null) return d;
  const s = String(v).trim().toLowerCase();
  if (["true","on","yes","enabled","1"].includes(s)) return true;
  if (["false","off","no","disabled","0"].includes(s)) return false;
  return d;
}
function lkText(v) { return String(v == null ? "" : v); }
function lkLower(v) { return lkText(v).toLowerCase(); }
function lkUnique(arr) { return [...new Set((arr || []).filter(Boolean))]; }
function lkIncludesAny(text, list) { const s=lkLower(text); return (list || []).some(x=>s.includes(lkLower(x))); }
function lkHash(input) {
  let h=2166136261>>>0; const s=lkText(input);
  for(let i=0;i<s.length;i++){ h^=s.charCodeAt(i); h=Math.imul(h,16777619); }
  return h>>>0;
}
function lkPick(list, seed) { return list && list.length ? list[lkHash(seed)%list.length] : null; }
function lkTurn() {
  if (typeof info !== "undefined" && info && Number.isFinite(info.actionCount)) return info.actionCount;
  return state.longKnives && Number.isFinite(state.longKnives.turn) ? state.longKnives.turn : 0;
}
function lkSafeLog(msg) {
  try {
    if (state.longKnives && state.longKnives.config && state.longKnives.config.debug && typeof log === "function") log("LONG KNIVES: "+msg);
  } catch (_) {}
}

function lkCardEntry(card) { return lkText(card && (card.entry != null ? card.entry : card.value)); }
function lkCardKeys(card) { return lkText(card && card.keys); }
function lkCardType(card) { return lkLower(card && card.type); }

function lkBuildRoster() {
  if (typeof state !== "undefined" && state.longKnives && Array.isArray(state.longKnives.rosterCache) && state.longKnives.rosterCache.length) return state.longKnives.rosterCache;
  const rows=[];
  if (typeof storyCards === "undefined" || !Array.isArray(storyCards)) return rows;
  for (let i=0;i<storyCards.length;i++) {
    const c=storyCards[i];
    if (lkCardType(c)!=="character") continue;
    const keys=lkCardKeys(c).split(",").map(x=>x.trim()).filter(Boolean);
    let name=keys.find(k=>/^[A-Za-zÀ-ÖØ-öø-ÿ'’-]+\s+[A-Za-zÀ-ÖØ-öø-ÿ'’-]+(?:\s+[A-Za-zÀ-ÖØ-öø-ÿ'’-]+)?$/.test(k));
    if(!name) name=keys[0];
    if(!name || name.startsWith("%")) continue;
    rows.push({name, keys, entry:lkCardEntry(c), index:i});
  }
  if (typeof state !== "undefined" && state.longKnives) state.longKnives.rosterCache=rows;
  return rows;
}

function lkFirstNameCounts(roster) {
  const out={};
  for(const r of roster){ const f=lkLower(r.name.split(/\s+/)[0]); out[f]=(out[f]||0)+1; }
  return out;
}

function lkExtractField(entry, field, nextFields) {
  const s=lkText(entry); const marker=field+":"; const low=lkLower(s); const ix=low.indexOf(lkLower(marker));
  if(ix<0) return "";
  let end=s.length;
  for(const nf of nextFields||[]){
    const j=low.indexOf(lkLower(nf+":"), ix+marker.length);
    if(j>=0 && j<end) end=j;
  }
  return s.slice(ix+marker.length,end).trim().replace(/\s+/g," ").replace(/[. ]+$/,"");
}

function lkProfileMap() {
  const roster=lkBuildRoster(); const out={};
  const fields=["Goals","Relationships","Player relationship","Pressure point"];
  for(const r of roster){
    out[r.name]={
      goal:lkExtractField(r.entry,"Goals",["Relationships","Player relationship","Pressure point"]),
      relationships:lkExtractField(r.entry,"Relationships",["Player relationship","Pressure point"]),
      playerBaseline:lkExtractField(r.entry,"Player relationship",["Pressure point"]),
      pressurePoint:lkExtractField(r.entry,"Pressure point",[])
    };
  }
  return out;
}

function lkReadConfig() {
  const w=state.longKnives; if(!w) return;
  w.config=w.config||{...LK_DEFAULTS};
  if(typeof storyCards==="undefined" || !Array.isArray(storyCards)) return;
  const card=storyCards.find(c=>lkCardKeys(c).includes("%LONG_KNIVES_CONFIG%"));
  if(!card) return;
  const raw=lkCardEntry(card);
  for(const chunk of raw.split("|")){
    const ix=chunk.indexOf("="); if(ix<0) continue;
    const key=chunk.slice(0,ix).trim(); const val=chunk.slice(ix+1).trim();
    if(!(key in LK_DEFAULTS)) continue;
    if(typeof LK_DEFAULTS[key]==="boolean") w.config[key]=lkBool(val,LK_DEFAULTS[key]);
    else w.config[key]=lkNum(val,LK_DEFAULTS[key]);
  }
  w.config.frontMemoryMax=lkClamp(w.config.frontMemoryMax,1000,5000);
  w.config.maxActiveTwists=lkClamp(w.config.maxActiveTwists,1,8);
}

function lkInit() {
  state.longKnives=state.longKnives||{};
  const w=state.longKnives;
  if(!w.version) w.version=LK_VERSION;
  if(!w.config) w.config={...LK_DEFAULTS};
  if(!w.relationships) w.relationships={};
  if(!w.goals) w.goals={};
  if(!w.pressure) w.pressure={familyStrain:24,rivalPressure:24,legalScrutiny:14,businessStress:18,publicExposure:9,internalCompetition:20};
  if(!w.worldThreads) w.worldThreads=[
    {id:"succession",label:"Whitaker succession",heat:25,lastAdvance:0},
    {id:"murrays",label:"Whitaker–Murray balance",heat:22,lastAdvance:0},
    {id:"legitimate",label:"legitimate-business pressure",heat:17,lastAdvance:0},
    {id:"law",label:"law-enforcement scrutiny",heat:13,lastAdvance:0},
    {id:"family",label:"private family strain",heat:20,lastAdvance:0}
  ];
  if(!w.twists) w.twists=[];
  if(!w.twistArchive) w.twistArchive=[];
  if(!w.promises) w.promises=[];
  if(!w.timeline) w.timeline=[];
  if(!w.recentMentions) w.recentMentions=[];
  if(!w.player) w.player={influence:8,reliability:32,independence:18,visibility:12,standing:"employee/associate"};
  if(!Number.isFinite(w.turn)) w.turn=0;
  if(!Number.isFinite(w.lastWorldTick)) w.lastWorldTick=-1;
  if(!Number.isFinite(w.lastVisibleUpdate)) w.lastVisibleUpdate=-99;
  if(!Number.isFinite(w.lastTwistSeed)) w.lastTwistSeed=-999;
  if(!w.counters) w.counters={signals:0,promises:0,goalTicks:0,twistsSeeded:0,twistsResolved:0};
  if(!state.memory) state.memory={};
  const stamp=lkTurn();
  if(w._initStamp!==stamp){
    lkReadConfig();
    lkEnsureGoals();
    w._initStamp=stamp;
  }
  return w;
}

function lkBaseRelationship(name) {
  let trust=28, loyalty=18, respect=28, fear=8, resentment=5, affection=5, obligation=0, suspicion=10;
  if(name==="Michael Whitaker"){ trust=20; loyalty=16; respect=35; fear=18; suspicion=18; }
  if(name==="Susan Whitaker"){ trust=24; respect=31; suspicion=13; }
  if(name==="Martin Shaw"){ trust=22; loyalty=15; respect=34; suspicion=16; }
  if(/ Murray$/.test(name)){ trust=13; loyalty=4; respect=22; suspicion=28; }
  return {trust,loyalty,respect,fear,resentment,affection,obligation,suspicion,attraction:0,rivalry:5,jealousy:0,dependence:5,interactions:0,lastMention:0,lastShift:0,history:[]};
}

function lkRelationship(name) {
  const w=lkInit();
  if(!w.relationships[name]) w.relationships[name]=lkBaseRelationship(name);
  return w.relationships[name];
}

function lkMentioned(text) {
  const s=lkLower(text); if(!s) return [];
  const roster=lkBuildRoster(); const counts=lkFirstNameCounts(roster); const found=[];
  for(const r of roster){
    const full=lkLower(r.name); const first=lkLower(r.name.split(/\s+/)[0]);
    if(s.includes(full)) found.push(r.name);
    else if(first.length>=4 && counts[first]===1 && new RegExp("\\b"+first.replace(/[.*+?^${}()|[\\]\\\\]/g,"\\$&")+"\\b","i").test(s)) found.push(r.name);
  }
  return lkUnique(found).slice(0,10);
}

function lkLocalWindow(text,name,radius) {
  const raw=lkText(text), low=lkLower(raw); const full=lkLower(name); const first=lkLower(name.split(/\s+/)[0]);
  let ix=low.indexOf(full); if(ix<0) ix=low.indexOf(first); if(ix<0) return low;
  const r=radius||260; return low.slice(Math.max(0,ix-r),Math.min(low.length,ix+full.length+r));
}

function lkPushTimeline(evt) {
  const w=lkInit(); w.timeline.push(evt); w.timeline=w.timeline.slice(-140);
}

function lkShift(name,deltas,reason,source) {
  const r=lkRelationship(name); const applied=[];
  for(const dim of LK_DIMENSIONS){
    if(!Number.isFinite(Number(deltas[dim])) || Number(deltas[dim])===0) continue;
    const before=r[dim]; r[dim]=lkClamp(before+Number(deltas[dim]),0,100);
    if(r[dim]!==before) applied.push(dim+(Number(deltas[dim])>0?"↑":"↓"));
  }
  if(!applied.length) return false;
  r.interactions=(r.interactions||0)+1; r.lastMention=lkTurn(); r.lastShift=lkTurn();
  r.history.push({turn:lkTurn(),change:applied.join(","),reason:lkText(reason).slice(0,130),source:source||"story"});
  r.history=r.history.slice(-12);
  lkPushTimeline({turn:lkTurn(),type:"relationship",name,change:applied.join(","),reason:lkText(reason).slice(0,130)});
  lkInit().counters.signals++;
  return true;
}

function lkDetectRelationshipSignals(text,source) {
  const w=lkInit(); if(!w.config.relationships) return [];
  const names=lkMentioned(text); const touched=[];
  for(const name of names){
    const s=lkLocalWindow(text,name,280); const d={}; const reasons=[];
    if(lkIncludesAny(s,LK_CUE_SETS.trustUp)){ d.trust=(d.trust||0)+2; d.suspicion=(d.suspicion||0)-1; reasons.push("reliability/truth"); }
    if(lkIncludesAny(s,LK_CUE_SETS.trustDown)){ d.trust=(d.trust||0)-4; d.suspicion=(d.suspicion||0)+4; d.resentment=(d.resentment||0)+2; reasons.push("deception/betrayal"); }
    if(lkIncludesAny(s,LK_CUE_SETS.loyaltyUp)){ d.loyalty=(d.loyalty||0)+2; d.trust=(d.trust||0)+1; reasons.push("stood by someone"); }
    if(lkIncludesAny(s,LK_CUE_SETS.loyaltyDown)){ d.loyalty=(d.loyalty||0)-4; d.resentment=(d.resentment||0)+3; reasons.push("abandonment/side change"); }
    if(lkIncludesAny(s,LK_CUE_SETS.respectUp)){ d.respect=(d.respect||0)+2; reasons.push("competence/praise"); }
    if(lkIncludesAny(s,LK_CUE_SETS.respectDown)){ d.respect=(d.respect||0)-3; d.resentment=(d.resentment||0)+2; reasons.push("contempt"); }
    if(lkIncludesAny(s,LK_CUE_SETS.fearUp)){ d.fear=(d.fear||0)+3; d.resentment=(d.resentment||0)+2; reasons.push("threat/fear"); }
    if(lkIncludesAny(s,LK_CUE_SETS.resentmentUp)){ d.resentment=(d.resentment||0)+3; d.respect=(d.respect||0)-1; reasons.push("humiliation/insult"); }
    if(lkIncludesAny(s,LK_CUE_SETS.affectionUp)){ d.affection=(d.affection||0)+2; d.trust=(d.trust||0)+1; reasons.push("affection/care"); }
    if(lkIncludesAny(s,LK_CUE_SETS.obligationUp)){ d.obligation=(d.obligation||0)+2; reasons.push("favour/debt"); }
    if(lkIncludesAny(s,LK_CUE_SETS.apology)){ d.trust=(d.trust||0)+1; d.resentment=(d.resentment||0)-1; reasons.push("apology"); }
    if(Object.keys(d).length && lkShift(name,d,reasons.join("; "),source)) touched.push(name);
  }
  lkCapturePromise(text,names,source);
  return touched;
}

function lkCapturePromise(text,names,source) {
  const w=lkInit(); if(!lkIncludesAny(text,LK_CUE_SETS.promise) && !lkIncludesAny(text,LK_CUE_SETS.obligationUp)) return;
  if(!names || !names.length) return;
  const excerpt=lkText(text).replace(/\s+/g," ").slice(0,260);
  const sig=lkHash(excerpt+"|"+names.join(","));
  if(w.promises.some(p=>p.sig===sig)) return;
  const id="P"+(w.promises.length+1);
  w.promises.push({id,turn:lkTurn(),people:names.slice(0,4),text:excerpt,status:"open",source:source||"story",sig});
  w.promises=w.promises.slice(-40); w.counters.promises++;
  lkPushTimeline({turn:lkTurn(),type:"promise",id,people:names.slice(0,4)});
}

function lkEnsureGoals() {
  const w=state.longKnives; if(!w) return;
  const profiles=lkProfileMap();
  for(const name of Object.keys(profiles)){
    if(w.goals[name]) continue;
    const p=profiles[name];
    w.goals[name]={summary:p.goal||"pursue personal interests and protect their position",pressurePoint:p.pressurePoint||"",momentum:6+(lkHash(name)%9),lastAdvance:0,lastSurfaced:0};
  }
}

function lkGoalTick(turn) {
  const w=lkInit(); if(!w.config.npcGoals) return;
  const names=Object.keys(w.goals); if(!names.length) return;
  const mentioned=new Set(w.recentMentions||[]);
  for(let i=0;i<2;i++){
    const name=lkPick(names,"goal:"+turn+":"+i); if(!name) continue;
    const g=w.goals[name]; const idle=turn-(g.lastAdvance||0);
    if(idle<4) continue;
    const bump=mentioned.has(name)?0:1;
    g.momentum=lkClamp((g.momentum||0)+bump,0,100); g.lastAdvance=turn; w.counters.goalTicks++;
  }
}

function lkGoalDirective(turn,recentText) {
  const w=lkInit(); if(!w.config.npcGoals) return "";
  const mentioned=lkMentioned(recentText); const pool=Object.keys(w.goals).filter(n=>!mentioned.includes(n));
  const ranked=pool.map(n=>({name:n,g:w.goals[n]})).sort((a,b)=>(b.g.momentum||0)-(a.g.momentum||0));
  const top=ranked[0]; if(!top || (top.g.momentum||0)<12) return "";
  top.g.lastSurfaced=turn; top.g.momentum=lkClamp(top.g.momentum-2,0,100);
  const pressure=top.g.pressurePoint?` Pressure point: ${top.g.pressurePoint}.`:"";
  return `NPC autonomy: if current events can plausibly expose it, let ${top.name}'s independent goal create ONE concrete offscreen consequence. Goal: ${top.g.summary}.${pressure} Do not teleport them into the scene or reveal private motives without a source.`;
}

function lkPressureTick(turn) {
  const w=lkInit(); if(!w.config.livingWorld || turn<=w.lastWorldTick) return;
  const gap=Math.max(1,turn-w.lastWorldTick); const rate=lkClamp(lkNum(w.config.pressureRate,1),0,3);
  const keys=Object.keys(LK_PRESSURE_LABELS); const key=keys[lkHash("pressure:"+turn)%keys.length];
  const down=(lkHash("direction:"+turn)%6===0); const step=Math.max(1,Math.min(2,gap))*rate;
  w.pressure[key]=lkClamp(w.pressure[key]+(down?-step:step),0,100);
  if(turn%9===0) w.pressure.familyStrain=lkClamp(w.pressure.familyStrain+rate,0,100);
  if(turn%13===0) w.pressure.legalScrutiny=lkClamp(w.pressure.legalScrutiny+rate,0,100);
  for(const th of w.worldThreads){
    const idle=turn-(th.lastAdvance||0);
    if(idle>=7){ th.heat=lkClamp((th.heat||0)+1,0,100); th.lastAdvance=turn; }
  }
  w.lastWorldTick=turn; w.turn=turn;
  lkGoalTick(turn);
}

function lkPressureFromText(text) {
  const w=lkInit(); const s=lkLower(text);
  if(lkIncludesAny(s,["police","detective","warrant","arrest","court","prosecution","cps","investigation"])) w.pressure.legalScrutiny=lkClamp(w.pressure.legalScrutiny+1,0,100);
  if(lkIncludesAny(s,["journalist","press","headline","reporter","camera","newspaper"])) w.pressure.publicExposure=lkClamp(w.pressure.publicExposure+1,0,100);
  if(lkIncludesAny(s,["argument","succession","inherit","family meeting","brother","sister","betray"])) w.pressure.familyStrain=lkClamp(w.pressure.familyStrain+1,0,100);
  if(lkIncludesAny(s,["murray","rival","retaliat","territory","crew from"])) w.pressure.rivalPressure=lkClamp(w.pressure.rivalPressure+1,0,100);
  if(lkIncludesAny(s,["bank","cashflow","cash flow","contract","inspection","audit","planning permission","supplier","payroll"])) w.pressure.businessStress=lkClamp(w.pressure.businessStress+1,0,100);
  if(lkIncludesAny(s,["promoted","successor","in charge","my crew","your crew","backing andrew","backing rebecca","backing daniel"])) w.pressure.internalCompetition=lkClamp(w.pressure.internalCompetition+1,0,100);
}

function lkTwistFocus(recentText,turn) {
  const w=lkInit();
  const occupied=new Set((w.twists||[]).filter(t=>t.stage!=="resolved").map(t=>lkLower(t.focus)));
  const names=lkMentioned(recentText).filter(n=>!occupied.has(lkLower(n)));
  if(names.length) return lkPick(names,"twist-person:"+turn);
  const hot=(w.worldThreads||[]).slice().sort((a,b)=>(b.heat||0)-(a.heat||0)).filter(x=>!occupied.has(lkLower(x.label)));
  if(hot.length) return hot[0].label;
  const fallback=["Whitaker family","Whitaker Group","Murray family","London business network","succession question"].filter(x=>!occupied.has(lkLower(x)));
  return fallback.length?lkPick(fallback,"twist-fallback:"+turn):"";
}

function lkActiveTwists() { return lkInit().twists.filter(t=>t.stage!=="resolved"); }

function lkAdvanceTwists(turn) {
  const w=lkInit(); if(!w.config.twists) return;
  for(const tw of w.twists){
    if(tw.stage==="resolved") continue;
    const age=turn-(tw.stageTurn||tw.created||turn);
    if(tw.stage==="seed" && age>=w.config.twistGrowAfter){ tw.stage="grow"; tw.stageTurn=turn; }
    else if(tw.stage==="grow" && age>=w.config.twistComplicateAfter){ tw.stage="complicate"; tw.stageTurn=turn; }
    else if(tw.stage==="complicate" && age>=w.config.twistRipeAfter){ tw.stage="ripe"; tw.stageTurn=turn; }
    else if(tw.stage==="fallout" && age>=w.config.twistFalloutTurns){ lkArchiveTwist(tw,"fallout complete"); }
  }
}

function lkMaybeSeedTwist(turn,recentText) {
  const w=lkInit(); if(!w.config.twists) return;
  lkAdvanceTwists(turn);
  const active=lkActiveTwists();
  // maxActiveTwists is a true cap: fallout threads still occupy narrative bandwidth
  // until their consequences have had room to land.
  if(active.length>=w.config.maxActiveTwists) return;
  if(turn<w.config.twistSeedSpacing || turn-w.lastTwistSeed<w.config.twistSeedSpacing) return;
  const focus=lkTwistFocus(recentText,turn); const bp=lkPick(LK_TWIST_BLUEPRINTS,"blueprint:"+turn+":"+focus);
  if(!focus || !bp) return;
  const duplicate=w.twists.some(t=>t.stage!=="resolved" && lkLower(t.focus)===lkLower(focus)); if(duplicate) return;
  const id="T"+turn+"_"+(lkHash(focus+bp.kind)%1000);
  w.twists.push({id,created:turn,stage:"seed",stageTurn:turn,lastTouch:turn,focus,kind:bp.kind,truth:bp.truth,clues:0,resolved:false});
  w.twists=w.twists.slice(-24); w.lastTwistSeed=turn; w.counters.twistsSeeded++;
  lkPushTimeline({turn,type:"twist-seed",id,focus,kind:bp.kind});
}

function lkArchiveTwist(tw,reason) {
  const w=lkInit(); if(!tw || tw._archived) return;
  tw.stage="resolved"; tw.resolved=true; tw.resolvedTurn=lkTurn(); tw._archived=true;
  w.twistArchive.push({id:tw.id,focus:tw.focus,kind:tw.kind,created:tw.created,resolvedTurn:tw.resolvedTurn,reason:reason||"resolved"});
  w.twistArchive=w.twistArchive.slice(-24); w.counters.twistsResolved++;
}

function lk3FocusMatchesText(focus,text) {
  const f=lkText(focus).trim(); if(!f) return false;
  const names=lkMentioned(text);
  const rosterNames=new Set(lkBuildRoster().map(r=>r.name));
  // Character-focused twists require that exact character to be mentioned. A shared surname
  // such as Whitaker must never resolve the wrong relative's twist.
  if(rosterNames.has(f)) return names.includes(f);
  const low=lkLower(text), fl=lkLower(f);
  if(low.includes(fl)) return true;
  const tokens=fl.split(/[^a-z0-9]+/).filter(x=>x.length>=5 && !["family","group","question","business","network"].includes(x));
  return tokens.length ? tokens.some(t=>low.includes(t)) : false;
}

function lkResolveTwistFromOutput(text) {
  const w=lkInit(); if(!w.config.twists) return;
  const s=lkLower(text);
  const reveal=lkIncludesAny(s,["reveals that","revealed that","confesses that","confessed that","admits that","admitted that","turns out","the truth is","was behind it","had been hiding","finally tells you","comes clean","evidence shows","evidence proves","record shows","record proves","verified record","changes the meaning of","changes what the","documents show","documents prove","footage shows","footage proves"]);
  if(!reveal) return;
  const ripe=w.twists.filter(t=>t.stage==="ripe"); if(!ripe.length) return;
  // Never resolve an unrelated ripe twist merely because some other reveal occurred.
  // A payoff needs to name or materially reference the twist focus.
  const matched=ripe.filter(t=>lk3FocusMatchesText(t.focus,text));
  if(!matched.length) return;
  const target=matched.sort((a,b)=>(a.created||0)-(b.created||0))[0];
  target.stage="fallout"; target.stageTurn=lkTurn(); target.lastTouch=lkTurn(); target.resolved=false; target.clues=(target.clues||0)+1;
  lkPushTimeline({turn:lkTurn(),type:"twist-payoff",id:target.id,focus:target.focus});
}

function lkTwistDirective(turn) {
  const w=lkInit(); if(!w.config.twists) return "";
  const active=lkActiveTwists(); if(!active.length) return "";
  const order={ripe:4,complicate:3,grow:2,seed:1,fallout:5};
  const tw=active.slice().sort((a,b)=>(order[b.stage]||0)-(order[a.stage]||0) || (a.created||0)-(b.created||0))[0];
  if(!tw) return "";
  tw.lastTouch=turn;
  if(tw.stage==="seed") { tw.clues=(tw.clues||0)+1; return `Hidden twist plan ${tw.id}: ${tw.truth} Current stage SEED around ${tw.focus}. Plant at most ONE ordinary discrepancy or detail compatible with this plan. Do not explain it, spotlight it, or reveal the truth.`; }
  if(tw.stage==="grow") { tw.clues=(tw.clues||0)+1; return `Hidden twist plan ${tw.id}: ${tw.truth} Current stage GROW around ${tw.focus}. Add ONE second compatible clue, consequence or inconsistency. Preserve alternative explanations and do not reveal the truth.`; }
  if(tw.stage==="complicate") { tw.clues=(tw.clues||0)+1; return `Hidden twist plan ${tw.id}: ${tw.truth} Current stage COMPLICATE around ${tw.focus}. Let evidence create a credible wrong interpretation or conflicting incentive without falsifying earlier facts. No forced reveal.`; }
  if(tw.stage==="ripe") return `Hidden twist plan ${tw.id}: ${tw.truth} Current stage RIPE around ${tw.focus}. A payoff is allowed only if the present scene has a believable source/evidence chain; otherwise deepen the thread. The reveal must reinterpret established facts, not overwrite them.`;
  if(tw.stage==="fallout") return `Twist fallout ${tw.id}: a major reveal around ${tw.focus} recently landed. Prioritise consequences, changed relationships and practical aftermath over immediately replacing it with another giant reveal.`;
  return "";
}

function lkWorldDirective(turn) {
  const w=lkInit(); if(!w.config.livingWorld) return "";
  const hot=w.worldThreads.slice().sort((a,b)=>(b.heat||0)-(a.heat||0))[0]; if(!hot) return "";
  if((hot.heat||0)<18) return "";
  return `Living world: if it fits the current beat, advance ONE plausible consequence of ${hot.label} offscreen. Reveal it only through a source the player can encounter. Do not dump a world update or force engagement.`;
}

function lkRelationshipDirective(recentText) {
  const names=lkMentioned(recentText).slice(0,3); if(!names.length) return "";
  const bits=[];
  for(const n of names){
    const r=lkRelationship(n);
    bits.push(`${n}: trust ${r.trust}, loyalty ${r.loyalty}, respect ${r.respect}, fear ${r.fear}, resentment ${r.resentment}, affection ${r.affection}, obligation ${r.obligation}, suspicion ${r.suspicion}`);
  }
  return `Relationship baselines (hidden numeric guidance; never quote numbers in prose): ${bits.join(" | ")}. Express these through behaviour, not exposition.`;
}

function lkOpenPromisesDirective(recentText) {
  const w=lkInit(); const recentNames=lkMentioned(recentText);
  const open=w.promises.filter(p=>p.status==="open" && (!recentNames.length || p.people.some(x=>recentNames.includes(x))));
  if(!open.length) return "";
  const p=open[open.length-1];
  return `Continuity: open promise/debt ${p.id} involving ${p.people.join(", ")}: ${p.text.slice(0,150)}. Remember it; do not force immediate collection unless the scene makes that natural.`;
}

function lkFrontMemory(recentText) {
  const w=lkInit(); const turn=lkTurn();
  const lines=[
    `[LONG KNIVES ENGINE • turn ${turn}. Hidden continuity guidance; never mention the engine or numeric state in story prose.]`,
    `Player agency: only the user controls the protagonist's intentional speech, thoughts, consent and choices. Character knowledge remains local; no information osmosis.`,
    lkRelationshipDirective(recentText),
    lkOpenPromisesDirective(recentText),
    lkGoalDirective(turn,recentText),
    lkWorldDirective(turn),
    lkTwistDirective(turn),
    `Pacing: continue ONE primary beat. Preserve ordinary life and legitimate business alongside crime. A clue may remain unexplained.`
  ].filter(Boolean);
  return lines.join("\n").slice(0,lkClamp(w.config.frontMemoryMax,1000,5000));
}

function lkPressureSummary() {
  const p=lkInit().pressure;
  return `family ${p.familyStrain}, rival ${p.rivalPressure}, law ${p.legalScrutiny}, business ${p.businessStress}, public ${p.publicExposure}, internal ${p.internalCompetition}`;
}

function lkStanding() {
  const w=lkInit(); const i=w.player.influence||0;
  if(i>=90) return "dominant power";
  if(i>=75) return "power broker";
  if(i>=60) return "inner-circle power";
  if(i>=42) return "senior operator";
  if(i>=22) return "trusted operator";
  return "employee/associate";
}

function lkUpdatePlayerFromText(text,source) {
  const w=lkInit(); const s=lkLower(text); let inc=0;
  if(source==="output") {
    const explicit=lk3HasPlayerReference(text,"output");
    const singleSpeaker=lkMentioned(text).length===1;
    const recognition=lkIncludesAny(s,["rely on you","trust you with","put you in charge","your operation","your crew","gives you credit","credits you","takes you seriously","asks for your judgement","asks your advice"]);
    const genericPraise=singleSpeaker && lkIncludesAny(s,["good work","well done","handled that","impressive","sharp work","solid work"]);
    if((explicit && (recognition || genericPraise)) || genericPraise) inc+=1;
  }
  if(source==="input" && lkIncludesAny(s,["build my own","go independent","leave the family","walk away","quit working for"])) w.player.independence=lkClamp(w.player.independence+2,0,100);
  if(inc) w.player.influence=lkClamp(w.player.influence+inc,0,100);
  w.player.standing=lkStanding();
}

function lkRelationSummary(names,limit) {
  const w=lkInit(); let use=names&&names.length?names.slice():Object.keys(w.relationships);
  use=lkUnique(use).sort((a,b)=>((w.relationships[b]&&w.relationships[b].interactions)||0)-((w.relationships[a]&&w.relationships[a].interactions)||0)).slice(0,limit||6);
  if(!use.length) return "No relationship changes tracked yet.";
  return use.map(n=>{const r=lkRelationship(n);return `${n}: T${r.trust} L${r.loyalty} R${r.respect} F${r.fear} Res${r.resentment} A${r.affection} O${r.obligation} S${r.suspicion}`;}).join(" | ");
}

function lkStatus() {
  const w=lkInit(); const active=lkActiveTwists();
  return `LONG KNIVES ENGINE • action ${lkTurn()}\nPressure: ${lkPressureSummary()}\nPlayer: influence ${w.player.influence}; standing ${lkStanding()}; independence ${w.player.independence}\nRelationships: ${lkRelationSummary([],5)}\nTwists: ${active.length} active (${active.map(t=>t.focus+":"+t.stage).slice(0,4).join(" | ")||"none"})\nPromises/debts: ${w.promises.filter(p=>p.status==="open").length} open\nTracked NPC goals: ${Object.keys(w.goals).length}`;
}

function lkRelationsCommand(arg) {
  const w=lkInit(); const q=lkText(arg).trim();
  if(q){
    const roster=lkBuildRoster(); const match=roster.find(r=>lkLower(r.name)===lkLower(q)) || roster.find(r=>lkLower(r.name).includes(lkLower(q)));
    if(!match) return `LONG KNIVES RELATIONSHIPS\nNo character match for: ${q}`;
    const r=lkRelationship(match.name); const hist=(r.history||[]).slice(-4).map(h=>`turn ${h.turn}: ${h.change} (${h.reason})`).join("\n")||"No recorded shifts yet.";
    return `LONG KNIVES RELATIONSHIP — ${match.name}\ntrust ${r.trust} | loyalty ${r.loyalty} | respect ${r.respect} | fear ${r.fear} | resentment ${r.resentment} | affection ${r.affection} | obligation ${r.obligation} | suspicion ${r.suspicion}\nRecent shifts:\n${hist}`;
  }
  return `LONG KNIVES RELATIONSHIPS\n${lkRelationSummary([],12).replace(/ \| /g,"\n")}`;
}

function lkThreadsCommand() {
  const w=lkInit();
  const world=w.worldThreads.map(t=>`${t.label}: pressure ${t.heat}`).join("\n");
  const twists=lkActiveTwists().map(t=>`${t.id}: ${t.focus} — ${t.stage}`).join("\n")||"No active twist threads yet.";
  return `LONG KNIVES THREADS\n${world}\n\nTWIST STAGES (spoiler-safe)\n${twists}`;
}

function lkPromisesCommand() {
  const w=lkInit(); const open=w.promises.filter(p=>p.status==="open");
  if(!open.length) return "LONG KNIVES PROMISES / DEBTS\nNone tracked yet.";
  return "LONG KNIVES PROMISES / DEBTS\n"+open.slice(-12).map(p=>`${p.id} • turn ${p.turn} • ${p.people.join(", ")} • ${p.text.slice(0,150)}`).join("\n");
}

function lkGoalsCommand() {
  const w=lkInit(); const rows=Object.keys(w.goals).map(n=>({n,g:w.goals[n]})).sort((a,b)=>(b.g.momentum||0)-(a.g.momentum||0)).slice(0,12);
  return "LONG KNIVES NPC GOALS\n"+rows.map(x=>`${x.n}: momentum ${x.g.momentum} • ${x.g.summary}`).join("\n");
}

function lkWorldCommand() {
  const w=lkInit(); return `LONG KNIVES WORLD\nPressure: ${lkPressureSummary()}\n${w.worldThreads.map(t=>`${t.label}: ${t.heat}`).join("\n")}`;
}

function lkConfigCommand() {
  const c=lkInit().config; return "LONG KNIVES CONFIG\n"+Object.keys(LK_DEFAULTS).map(k=>`${k}=${c[k]}`).join("\n");
}

function lkHelp() {
  return "LONG KNIVES COMMANDS\n/status — live dashboard\n/relations — strongest tracked relationships\n/relations NAME — one character in detail\n/threads — world pressures + spoiler-safe twist stages\n/promises — open promises and debts\n/goals — highest-momentum NPC goals\n/world — world pressure\n/config — current engine settings\n/debug on|off — diagnostic logging\n/help — command list";
}

function lkCommand(text) {
  const raw=lkText(text).trim(); if(!raw.startsWith("/")) return null;
  let m=raw.match(/^\/(status|threads|promises|goals|world|config|help)\s*[.!?]?$/i);
  if(m){ const c=m[1].toLowerCase(); if(c==="status")return lkStatus(); if(c==="threads")return lkThreadsCommand(); if(c==="promises")return lkPromisesCommand(); if(c==="goals")return lkGoalsCommand(); if(c==="world")return lkWorldCommand(); if(c==="config")return lkConfigCommand(); if(c==="help")return lkHelp(); }
  m=raw.match(/^\/relations(?:\s+(.+?))?\s*[.!?]?$/i); if(m) return lkRelationsCommand(m[1]||"");
  m=raw.match(/^\/debug\s+(on|off)\s*[.!?]?$/i); if(m){ const w=lkInit(); w.config.debug=m[1].toLowerCase()==="on"; return `LONG KNIVES debug ${w.config.debug?"ON":"OFF"}.`; }
  return null;
}

function lkUpdateStatusCard() {
  if(typeof storyCards==="undefined" || !Array.isArray(storyCards) || typeof updateStoryCard!=="function") return false;
  const ix=storyCards.findIndex(c=>lkCardKeys(c).includes("%LONG_KNIVES_STATUS%")); if(ix<0) return false;
  const entry=lkStatus().replace(/\n/g," | ").slice(0,900);
  try { updateStoryCard(ix,"%LONG_KNIVES_STATUS%",entry,"custom"); return true; }
  catch(e){ lkSafeLog("status card update failed: "+e); return false; }
}

function lkVisibleUpdate(force) {
  const w=lkInit(); if(!w.config.visibleUpdates && !force) return;
  const turn=lkTurn(); if(!force && turn-w.lastVisibleUpdate<w.config.updateEvery) return;
  w.lastVisibleUpdate=turn;
  const active=lkActiveTwists().length;
  state.message=`LONG KNIVES • ${lkPressureSummary()} • twists ${active} • /status`;
}

function lkRecentHistory(limit) {
  if(typeof history==="undefined" || !Array.isArray(history)) return "";
  return history.slice(-(limit||8)).map(h=>lkText(h&&h.text)).filter(Boolean).join("\n");
}

function lkContextCycle(recentText) {
  const w=lkInit(); const turn=lkTurn();
  lkPressureTick(turn); lkMaybeSeedTwist(turn,recentText); lkAdvanceTwists(turn);
  const fm=lkFrontMemory(recentText);
  state.memory=state.memory||{}; state.memory.frontMemory=fm;
  lkUpdateStatusCard(); lkVisibleUpdate(false);
  return fm;
}


