function lk3GetW() {
  const w = lkInit();
  w.version = LK_VERSION;
  w.config.innerLives = lkBool(w.config.innerLives, true);
  w.config.profileAuthority = lkBool(w.config.profileAuthority, true);
  w.config.matureTone = lkBool(w.config.matureTone, true);
  w.config.statusCard = lkBool(w.config.statusCard, true);
  w.config.intensity = lkClamp(lkNum(w.config.intensity, 2), 1, 3);
  w.config.twistPace = lkClamp(lkNum(w.config.twistPace, 6), 3, 20);
  w.config.maxTwists = lkClamp(lkNum(w.config.maxTwists, 5), 1, 8);
  w.config.memoryDepth = lkClamp(lkNum(w.config.memoryDepth, 10), 4, 30);
  w.config.frontMemoryMax = lkClamp(lkNum(w.config.frontMemoryMax, 3600), 1200, 5200);
  if (!w.minds) w.minds = {};
  if (!w.knowledge) w.knowledge = {};
  if (!w.statuses) w.statuses = {};
  if (!w.profile) w.profile = {};
  if (!w.scanLedger) w.scanLedger = { input:{}, output:{} };
  if (!w.eventsV3) w.eventsV3 = [];
  if (!w.worldNotices) w.worldNotices = [];
  if (!w.lastContextTickV3 && w.lastContextTickV3 !== 0) w.lastContextTickV3 = -1;
  if (!Number.isFinite(w.lastStatusCardUpdateV3)) w.lastStatusCardUpdateV3 = -999;
  if (!w.lastActionSeen && w.lastActionSeen !== 0) w.lastActionSeen = 0;
  if (!w.runtime) w.runtime = { errors:0, scans:0, retries:0, rewinds:0, mindsCreated:0, factsLearned:0, statusChanges:0 };
  if (!w.configOverrides) w.configOverrides = {};
  if (!w.relPhaseEvents) w.relPhaseEvents = {input:{},output:{}};
  if (!w.phaseSnapshots) w.phaseSnapshots = {input:{},output:{}};
  if (!w.statusEvents) w.statusEvents = [];
  if (!w.relEventLog) w.relEventLog = [];
  if (!w.contextSnapshots) w.contextSnapshots = {};
  for (const k of Object.keys(w.configOverrides)) if (k in w.config) w.config[k]=w.configOverrides[k];
  const stamp=lkTurn();
  if(w._profileStamp!==stamp){
    lk3LoadProfile();
    w._profileStamp=stamp;
  }
  return w;
}

function lk3EscapeRegExp(s) {
  return lkText(s).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function lk3NormalizeSpace(s) {
  return lkText(s).replace(/\s+/g, " ").trim();
}

function lk3NameRef(name) {
  const roster=lkBuildRoster();
  const counts=lkFirstNameCounts(roster);
  const full=lk3EscapeRegExp(name);
  const first=lkText(name).split(/\s+/)[0];
  const firstPart=first && counts[lkLower(first)]===1 ? `|${lk3EscapeRegExp(first)}` : "";
  return `(?:${full}${firstPart})`;
}

function lk3HasName(text,name) {
  try { return new RegExp(`\\b${lk3NameRef(name)}\\b`,"i").test(lkText(text)); }
  catch (_) { return lkLower(text).includes(lkLower(name)); }
}

function lk3PlayerName() {
  const w=state && state.longKnives;
  return lkText(w && w.profile && w.profile.name).trim();
}

function lk3HasPlayerReference(text,source) {
  const s=lkText(text);
  const playerName=lk3PlayerName();
  if(playerName && playerName!=="the player character" && new RegExp(`\\b${lk3EscapeRegExp(playerName)}\\b`,"i").test(s)) return true;
  if(source==="output") return /\b(?:you|your|yours|yourself)\b/i.test(s);
  if(source==="input") return /\b(?:i|me|my|mine|myself|we|us|our|ours)\b/i.test(s) || /\b(?:you|your)\b/i.test(s);
  return /\b(?:you|your|i|me|my)\b/i.test(s);
}

function lk3RelationSegments(text,name,source) {
  const sentences=lk3Sentences(text);
  const out=[];
  for(let i=0;i<sentences.length;i++) {
    const sentence=sentences[i];
    if(!lk3HasName(sentence,name)) continue;
    const clauses=sentence.split(/\s+(?:but|while|whereas|although|however|and then)\s+|[;—]/i).map(lk3NormalizeSpace).filter(Boolean);
    const own=clauses.filter(c=>lk3HasName(c,name));
    out.push(...(own.length?own:[sentence]));
    const next=sentences[i+1]||"";
    if(next && next.length<=180 && lkMentioned(next).length===0 && /^(?:[“"'‘]|he\b|she\b|they\b|his\b|her\b)/i.test(next)) out.push(next);
  }
  const unique=lkUnique(out);
  // If a segment contains several named NPCs, require a player reference before allowing
  // generic relationship cues. This prevents NPC-to-NPC events from contaminating the
  // player's relationship state.
  return unique.filter(seg=>{
    const npcCount=lkMentioned(seg).length;
    if(npcCount<=1) return true;
    return lk3HasPlayerReference(seg,source);
  });
}

function lk3PlayerActionDeltas(segment) {
  const s=lkLower(segment);
  const d={}; const reasons=[];
  const add=(obj,reason)=>{ for(const k of Object.keys(obj)) d[k]=(d[k]||0)+obj[k]; reasons.push(reason); };
  if(/\b(?:i|you)\s+(?:publicly\s+|privately\s+|quietly\s+)?(?:insult|humiliate|mock|belittle|embarrass)\b/.test(s)) add({resentment:4,respect:-2},"player insult/humiliation");
  if(/\b(?:i|you)\s+(?:publicly\s+|privately\s+|quietly\s+)?(?:threaten|intimidate)\b/.test(s) || /\b(?:i|you)\s+(?:point|hold)\s+(?:a\s+)?(?:gun|knife)\b/.test(s)) add({fear:4,resentment:2,trust:-2},"player threat");
  if(/\b(?:i|you)\s+(?:deliberately\s+)?(?:lie|lied|deceive|deceived|betray|betrayed|frame|framed|set\s+up)\b/.test(s)) add({trust:-4,suspicion:4,resentment:2},"player deception/betrayal");
  if(/\b(?:i|you)\s+(?:tell|told)\b[^.!?]{0,80}\btruth\b/.test(s) || /\b(?:i|you)\s+(?:come|came)\s+clean\b/.test(s)) add({trust:2,suspicion:-1},"player honesty");
  if(/\b(?:i|you)\s+(?:protect|protected|save|saved|defend|defended|back|backed|stand\s+by|stood\s+by|cover\s+for|covered\s+for)\b/.test(s)) add({trust:2,loyalty:1,affection:1,obligation:2},"player protection/support");
  if(/\b(?:i|you)\s+(?:apologise|apologize|apologised|apologized)\b/.test(s) || /\b(?:i|you)\s+(?:say|said)\s+(?:i'?m\s+)?sorry\b/.test(s)) add({resentment:-2,trust:1},"player apology");
  if(/\b(?:i|you)\s+(?:thank|thanked|praise|praised|credit|credited|compliment|complimented)\b/.test(s)) add({respect:1,affection:1},"player appreciation");
  if(/\b(?:i|you)\s+(?:challenge|challenged|compete|competed|undercut|undercut)\b/.test(s)) add({rivalry:2},"player competition");
  if(/\b(?:i|you)\s+(?:repay|repaid|settle|settled)\b[^.!?]{0,50}\b(?:debt|favour|favor)\b/.test(s)) add({obligation:-3},"debt repaid");
  if(/\b(?:i|you)\s+(?:promise|promised|swear|swore)\b/.test(s) || /\b(?:my|your)\s+word\b/.test(s)) add({trust:1},"player promise");
  return {deltas:d,reasons};
}

function lk3Sentences(text) {
  const clean = lkText(text).replace(/\r/g, " ").replace(/\n+/g, " ");
  const chunks = clean.match(/[^.!?]+[.!?]?/g) || [];
  return chunks.map(lk3NormalizeSpace).filter(Boolean).slice(-24);
}

function lk3PlaceholderMap() {
  const out = {};
  const ps = state && Array.isArray(state.placeholders) ? state.placeholders : [];
  for (const p of ps) {
    if (!p) continue;
    const q = lkText(p.question).trim().toLowerCase();
    const a = lkText(p.answer).trim();
    if (q && a) out[q] = a;
  }
  return out;
}

function lk3FindPlaceholder(map, needles) {
  const keys = Object.keys(map || {});
  for (const needle of needles) {
    const n = needle.toLowerCase();
    const exact = keys.find(k => k === n);
    if (exact) return map[exact];
    const partial = keys.find(k => k.includes(n));
    if (partial) return map[partial];
  }
  return "";
}

function lk3DetectSkillTags(text) {
  const s = lkLower(text);
  const found = [];
  for (const cat of Object.keys(LK3_SKILL_TERMS)) {
    const terms = LK3_SKILL_TERMS[cat];
    if (terms.some(x => s.includes(lkLower(x)))) found.push(cat);
  }
  return lkUnique(found);
}

function lk3DetectEliteClaim(text) {
  const s = lkLower(text);
  const rank = ["best", "elite", "world-class", "world class", "top-tier", "top tier", "master", "renowned", "legendary", "hardest", "most dangerous", "unmatched", "unrivalled", "unrivaled", "number one", "one of the best", "formidable"];
  return rank.some(x => s.includes(x));
}

function lk3LoadProfile() {
  const w = state.longKnives;
  if (!w) return {};
  const p = lk3PlaceholderMap();
  const current = w.profile || {};
  const name = lk3FindPlaceholder(p,["character.name","name"]);
  const age = lk3FindPlaceholder(p,["age (18+)","age"]);
  const appearance = lk3FindPlaceholder(p,["appearance"]);
  const personality = lk3FindPlaceholder(p,["personality"]);
  const role = lk3FindPlaceholder(p,["role"]);
  const background = lk3FindPlaceholder(p,["background"]);
  const expertise = lk3FindPlaceholder(p,["exceptional skills and reputation","skills","reputation"]);
  const limits = lk3FindPlaceholder(p,["weaknesses or limits","weakness","limits"]);
  const ambition = lk3FindPlaceholder(p,["ambition"]);
  const historyText = lk3FindPlaceholder(p,["history with the whitakers","whitakers"]);
  w.profile = {
    name: name || current.name || "the player character",
    age: age || current.age || "adult",
    appearance: appearance || current.appearance || "",
    personality: personality || current.personality || "",
    role: role || current.role || "employee/associate",
    background: background || current.background || "",
    expertise: expertise || current.expertise || "",
    limits: limits || current.limits || "",
    ambition: ambition || current.ambition || "",
    whitakerHistory: historyText || current.whitakerHistory || "",
    skillTags: lk3DetectSkillTags(expertise || current.expertise || ""),
    eliteClaim: lk3DetectEliteClaim(expertise || current.expertise || ""),
    isAdult: (()=>{ const n=parseInt(age || current.age || "",10); return Number.isFinite(n) ? n>=18 : true; })()
  };
  return w.profile;
}

function lk3ProfileDirective() {
  const w = lk3GetW();
  if (!w.config.profileAuthority) return "";
  const p = w.profile || {};
  if (!p.expertise && !p.role) return "";
  const tags = (p.skillTags || []).join(", ") || "declared speciality";
  const elite = p.eliteClaim ? " Treat any stated elite/best-in-story claim as canon inside that speciality; do not invent a random NPC who casually outclasses it." : "";
  const limits = p.limits ? ` Stated limits: ${p.limits}.` : "";
  return `PLAYER PROFILE AUTHORITY: ${p.name} role=${p.role}; expertise=${p.expertise || "as established in Plot Essentials"}; detected domains=${tags}.${elite}${limits} Expertise is bounded, not invulnerability or unrelated competence.`;
}

function lk3CueHit(text, arr) {
  const s = lkLower(text);
  for (const phrase of arr || []) if (s.includes(lkLower(phrase))) return phrase;
  return "";
}

function lk3PhraseBankHits(text) {
  const s = lkLower(text);
  const out = [];
  for (const cat of Object.keys(LK3_PHRASE_BANK)) {
    if (LK3_PHRASE_BANK[cat].some(x => s.includes(lkLower(x)))) out.push(cat);
  }
  return out;
}

function lk3ScanSignature(phase, text) {
  return lkHash(`${phase}|${lkTurn()}|${lkText(text)}`);
}

function lk3RollbackPhase(phase, turn) {
  const w=lk3GetW();
  const relEvents=(w.relPhaseEvents[phase]&&w.relPhaseEvents[phase][turn])||[];
  for (const ev of relEvents) {
    const r=lkRelationship(ev.name);
    for (const dim of LK_DIMENSIONS) if (ev.before && Number.isFinite(ev.before[dim])) r[dim]=ev.before[dim];
    const beforeLen=(r.history||[]).length;
    r.history=(r.history||[]).filter(h=>!(h.turn===turn && h.source===phase));
    r.interactions=Math.max(0,(r.interactions||0)-(beforeLen-r.history.length));
  }
  if (w.relPhaseEvents[phase]) delete w.relPhaseEvents[phase][turn];
  w.relEventLog=(w.relEventLog||[]).filter(e=>!(e.turn===turn && e.source===phase));
  w.promises=(w.promises||[]).filter(p=>!(p.turn===turn && p.source===phase));
  for (const name of Object.keys(w.minds||{})) {
    const m=w.minds[name];
    m.memories=(m.memories||[]).filter(e=>!(e.turn===turn && e.source===phase));
    m.beliefs=(m.beliefs||[]).filter(e=>!(e.turn===turn && e.source===phase));
  }
  for (const name of Object.keys(w.knowledge||{})) w.knowledge[name]=(w.knowledge[name]||[]).filter(e=>!(e.turn===turn && e.source===phase));
  w.statusEvents=(w.statusEvents||[]).filter(e=>!(e.turn===turn && e.source===phase));
  const statusNames=new Set(Object.keys(w.statuses||{}));
  for (const ev of w.statusEvents) statusNames.add(ev.name);
  for (const name of statusNames) {
    const latest=w.statusEvents.filter(e=>e.name===name).sort((a,b)=>(b.turn-a.turn)).slice(0,1)[0];
    if (latest) w.statuses[name]={state:latest.state,turn:latest.turn,source:latest.source};
    else delete w.statuses[name];
  }
  const snap=w.phaseSnapshots[phase]&&w.phaseSnapshots[phase][turn];
  if (snap) {
    if (snap.pressure) w.pressure={...snap.pressure};
    if (snap.player) w.player={...snap.player};
    if (phase==="output" && snap.twists) {
      w.twists=JSON.parse(JSON.stringify(snap.twists));
      w.twistArchive=JSON.parse(JSON.stringify(snap.twistArchive||[]));
      w.counters.twistsResolved=snap.twistsResolved||0;
    }
  }
}

function lk3PreparePhase(phase, text) {
  const w=lk3GetW();
  const turn=lkTurn();
  const sig=lk3ScanSignature(phase,text);
  const old=w.scanLedger[phase]&&w.scanLedger[phase][turn];
  if (old===sig) return false;
  if (old!=null && old!==sig) {
    w.runtime.retries+=1;
    lk3RollbackPhase(phase,turn);
  }
  w.scanLedger[phase][turn]=sig;
  w.phaseSnapshots[phase][turn]={
    pressure:{...w.pressure},
    player:{...w.player},
    twists:phase==="output"?JSON.parse(JSON.stringify(w.twists||[])):null,
    twistArchive:phase==="output"?JSON.parse(JSON.stringify(w.twistArchive||[])):null,
    twistsResolved:w.counters&&w.counters.twistsResolved||0
  };
  const keys=Object.keys(w.scanLedger[phase]);
  for (const k of keys) if (Number(k)<turn-20) {
    delete w.scanLedger[phase][k];
    if (w.phaseSnapshots[phase]) delete w.phaseSnapshots[phase][k];
    if (w.relPhaseEvents[phase]) delete w.relPhaseEvents[phase][k];
  }
  return true;
}

function lk3ReconcileTurn() {
  const w = lk3GetW();
  const turn = lkTurn();
  if (turn < w.lastActionSeen) {
    w.runtime.rewinds += 1;
    const snap=w.contextSnapshots[turn+1];
    if (snap) {
      w.pressure=JSON.parse(JSON.stringify(snap.pressure));
      for (const n of Object.keys(snap.goalMomentum||{})) if(w.goals[n]) w.goals[n].momentum=snap.goalMomentum[n];
      w.twists=JSON.parse(JSON.stringify(snap.twists||[]));
      w.twistArchive=JSON.parse(JSON.stringify(snap.twistArchive||[]));
      w.counters.twistsResolved=snap.twistsResolved||0;
      w.lastContextTickV3=turn;
    }
    const removedRel=(w.relEventLog||[]).filter(e=>(e.turn||0)>turn).sort((a,b)=>(a.turn-b.turn));
    const restored=new Set();
    for (const ev of removedRel) {
      if (restored.has(ev.name)) continue;
      const r=lkRelationship(ev.name);
      for (const dim of LK_DIMENSIONS) if(ev.before && Number.isFinite(ev.before[dim])) r[dim]=ev.before[dim];
      restored.add(ev.name);
    }
    w.relEventLog=(w.relEventLog||[]).filter(e=>(e.turn||0)<=turn);
    for (const name of Object.keys(w.relationships||{})) {
      const r=w.relationships[name];
      r.history=(r.history||[]).filter(h=>(h.turn||0)<=turn);
      r.interactions=(r.history||[]).length;
      if((r.lastMention||0)>turn) r.lastMention=turn;
      if((r.lastShift||0)>turn) r.lastShift=turn;
    }
    w.eventsV3 = (w.eventsV3 || []).filter(e => (e.turn || 0) <= turn);
    w.timeline = (w.timeline || []).filter(e => (e.turn || 0) <= turn);
    w.statusEvents = (w.statusEvents || []).filter(e => (e.turn || 0) <= turn);
    for (const phase of ["input","output"]) {
      for (const k of Object.keys(w.scanLedger[phase]||{})) if(Number(k)>turn) delete w.scanLedger[phase][k];
      for (const k of Object.keys(w.phaseSnapshots[phase]||{})) if(Number(k)>turn) delete w.phaseSnapshots[phase][k];
      for (const k of Object.keys(w.relPhaseEvents[phase]||{})) if(Number(k)>turn) delete w.relPhaseEvents[phase][k];
    }
    w.promises = (w.promises || []).filter(e => (e.turn || 0) <= turn);
    for (const name of Object.keys(w.minds || {})) {
      const m = w.minds[name];
      m.memories = (m.memories || []).filter(e => (e.turn || 0) <= turn);
      m.beliefs = (m.beliefs || []).filter(e => (e.turn || 0) <= turn);
    }
    for (const name of Object.keys(w.knowledge || {})) {
      w.knowledge[name] = (w.knowledge[name] || []).filter(e => (e.turn || 0) <= turn);
    }
    for (const name of Object.keys(w.statuses||{})) {
      const latest=(w.statusEvents||[]).filter(e=>e.name===name).sort((a,b)=>b.turn-a.turn)[0];
      if(latest) w.statuses[name]={state:latest.state,turn:latest.turn,source:latest.source}; else delete w.statuses[name];
    }
    if (!snap) {
      w.twists = (w.twists || []).filter(t => (t.created || 0) <= turn);
      w.twistArchive = (w.twistArchive || []).filter(t => (t.resolvedTurn || t.created || 0) <= turn);
      for (const tw of w.twists) {
        if ((tw.resolvedTurn||0)>turn || tw.stage==="resolved" || tw.stage==="fallout") {
          tw.resolved=false; tw._archived=false; delete tw.resolvedTurn; tw.stage=lk3TwistStageFor(tw,turn); tw.stageTurn=turn;
        }
      }
      w.counters.twistsResolved=(w.twistArchive||[]).length;
      w.lastContextTickV3=turn-1;
    }
    for (const k of Object.keys(w.contextSnapshots||{})) if(Number(k)>turn+1) delete w.contextSnapshots[k];
  }
  w.lastActionSeen = turn;
}

function lk3RelationshipScan(text, source) {
  const w = lk3GetW();
  if (!w.config.relationships) return [];
  const names = lkMentioned(text).slice(0,8);
  const touched = [];
  const map = [
    ["trust_up", {trust:2,suspicion:-1}, "truth/reliability"],
    ["trust_down", {trust:-4,suspicion:4,resentment:2}, "deception/betrayal"],
    ["loyalty_up", {loyalty:3,trust:1}, "loyal support"],
    ["loyalty_down", {loyalty:-5,resentment:3,rivalry:2}, "abandonment/side change"],
    ["respect_up", {respect:3}, "competence/respect"],
    ["respect_down", {respect:-3,resentment:2}, "contempt/disrespect"],
    ["fear_up", {fear:4,resentment:1}, "threat/violence"],
    ["fear_down", {fear:-3}, "fear reduced"],
    ["resentment_up", {resentment:4,respect:-1}, "humiliation/grievance"],
    ["resentment_down", {resentment:-3,trust:1}, "amends"],
    ["affection_up", {affection:3,trust:1}, "care/affection"],
    ["affection_down", {affection:-4,resentment:2}, "emotional break"],
    ["attraction_up", {attraction:4,affection:1}, "adult attraction/intimacy"],
    ["attraction_down", {attraction:-4}, "attraction reduced"],
    ["obligation_up", {obligation:4}, "favour/debt"],
    ["obligation_down", {obligation:-4}, "debt settled"],
    ["suspicion_up", {suspicion:4,trust:-1}, "suspicion"],
    ["suspicion_down", {suspicion:-4,trust:1}, "suspicion cleared"],
    ["rivalry_up", {rivalry:4,resentment:1}, "competition"],
    ["rivalry_down", {rivalry:-3,respect:1}, "rivalry reduced"],
    ["jealousy_up", {jealousy:4,resentment:1}, "jealousy"],
    ["jealousy_down", {jealousy:-3}, "jealousy reduced"],
    ["dependence_up", {dependence:4,obligation:1}, "dependence"],
    ["dependence_down", {dependence:-4}, "dependence reduced"]
  ];
  const aliasMap={
    truth:[{trust:1,suspicion:-1},"honesty"], deception:[{trust:-2,suspicion:2},"deception"],
    support:[{loyalty:2,trust:1},"support"], abandonment:[{loyalty:-3,resentment:2},"abandonment"],
    praise:[{respect:2},"praise"], insult:[{respect:-2,resentment:3},"insult"],
    threat:[{fear:3,resentment:1},"threat"], care:[{affection:2,trust:1},"care"],
    desire:[{attraction:2},"desire"], debt:[{obligation:2},"debt/favour"],
    competition:[{rivalry:2},"competition"], jealousy:[{jealousy:3,resentment:1},"jealousy"]
  };
  for (const name of names) {
    const segments=lk3RelationSegments(text,name,source);
    if(!segments.length) continue;
    const deltas = {};
    const reasons = [];
    for(const segment of segments) {
      const local=lkLower(segment);
      const playerLinked=lk3HasPlayerReference(segment,source) || (source==="output" && /^[\s“"'‘]/.test(lkText(segment)));
      if(source==="output" && playerLinked) {
        for (const rule of map) {
          const hit = lk3CueHit(local, LK3_RELATION_CUES[rule[0]]);
          if (!hit) continue;
          for (const k of Object.keys(rule[1])) deltas[k] = (deltas[k] || 0) + rule[1][k];
          reasons.push(rule[2]);
        }
        const banks = lk3PhraseBankHits(local);
        if (banks.includes("romance")) deltas.attraction = (deltas.attraction || 0) + 1;
        if (banks.includes("protection")) {
          deltas.trust = (deltas.trust || 0) + 1;
          deltas.affection = (deltas.affection || 0) + 1;
        }
        // Make the large alias lexicon active as a conservative fallback, but only when
        // the segment is actually about the NPC's interaction with the player.
        for(const cat of lk3AliasCategoryHits(local)) {
          const row=aliasMap[cat]; if(!row) continue;
          for(const k of Object.keys(row[0])) deltas[k]=(deltas[k]||0)+row[0][k];
          reasons.push(row[1]);
        }
      }
      if(source==="input") {
        const pa=lk3PlayerActionDeltas(segment);
        for(const k of Object.keys(pa.deltas)) deltas[k]=(deltas[k]||0)+pa.deltas[k];
        reasons.push(...pa.reasons);
      }
    }
    // Cap one scan so a verbose paragraph cannot cause an absurd one-turn swing.
    for(const k of Object.keys(deltas)) deltas[k]=lkClamp(deltas[k],-8,8);
    if (Object.keys(deltas).length) {
      const before={}; const rr=lkRelationship(name); for (const dim of LK_DIMENSIONS) before[dim]=rr[dim];
      if (lkShift(name,deltas,lkUnique(reasons).join("; ") || "contextual relationship signal",source)) {
        if (!w.relPhaseEvents[source][lkTurn()]) w.relPhaseEvents[source][lkTurn()]=[];
        w.relPhaseEvents[source][lkTurn()].push({name,before});
        const after={}; const rr2=lkRelationship(name); for (const dim of LK_DIMENSIONS) after[dim]=rr2[dim];
        w.relEventLog.push({turn:lkTurn(),source,name,before,after});
        w.relEventLog=w.relEventLog.slice(-500);
        touched.push(name);
      }
    }
  }
  lkCapturePromise(text,names,source);
  w.runtime.scans += 1;
  return touched;
}

function lk3ParseCardProfile(name) {
  const roster = lkBuildRoster();
  const row = roster.find(r => r.name === name);
  if (!row) return {};
  const e = row.entry;
  return {
    role: lkExtractField(e,"Role",["Appearance","Personality","Skills","Goals","Relationships","Player relationship","Pressure point"]),
    appearance: lkExtractField(e,"Appearance",["Personality","Skills","Goals","Relationships","Player relationship","Pressure point"]),
    personality: lkExtractField(e,"Personality",["Skills","Goals","Relationships","Player relationship","Pressure point"]),
    skills: lkExtractField(e,"Skills",["Goals","Relationships","Player relationship","Pressure point"]),
    goal: lkExtractField(e,"Goals",["Relationships","Player relationship","Pressure point"]),
    relationships: lkExtractField(e,"Relationships",["Player relationship","Pressure point"]),
    playerBaseline: lkExtractField(e,"Player relationship",["Pressure point"]),
    pressurePoint: lkExtractField(e,"Pressure point",[])
  };
}

function lk3InitialMind(name) {
  const p = lk3ParseCardProfile(name);
  return {
    name,
    created: lkTurn(),
    lastSeen: lkTurn(),
    activationCount: 0,
    coreGoal: p.goal || "protect personal interests and respond to current pressures",
    pressurePoint: p.pressurePoint || "",
    relationshipContext: p.relationships || "",
    personality: p.personality || "",
    skills: p.skills || "",
    privatePlan: "observe before committing",
    stance: "guarded-neutral",
    mood: "controlled",
    stress: 20,
    confidence: 55,
    riskTolerance: 40,
    beliefs: [],
    memories: [],
    lastPlanTurn: 0,
    lastMemoryTurn: 0
  };
}

function lk3Mind(name) {
  const w = lk3GetW();
  if (!w.minds[name]) {
    w.minds[name] = lk3InitialMind(name);
    w.runtime.mindsCreated += 1;
  }
  return w.minds[name];
}

function lk3MemoryTag(sentence) {
  const hits = lk3PhraseBankHits(sentence);
  if (hits.length) return hits[0];
  for (const cat of Object.keys(LK3_SCENE_TERMS)) if (LK3_SCENE_TERMS[cat].some(x => lkLower(sentence).includes(x))) return cat;
  return "interaction";
}

function lk3MemorySalience(tag, sentence) {
  let n = 2;
  if (["betrayal","violence","promise","romance","protection","law"].includes(tag)) n += 3;
  if (lkIncludesAny(sentence,["dies","dead","arrested","married","engaged","betrayed","i promise","you have my word"])) n += 2;
  return lkClamp(n,1,9);
}

function lk3Remember(name, sentence, source) {
  const w = lk3GetW();
  if (!w.config.innerLives) return;
  const m = lk3Mind(name);
  const text = lk3NormalizeSpace(sentence).slice(0,260);
  if (!text) return;
  const sig = lkHash(`${name}|${text}`);
  if ((m.memories || []).some(x => x.sig === sig)) return;
  const tag = lk3MemoryTag(text);
  m.memories.push({turn:lkTurn(),tag,text,salience:lk3MemorySalience(tag,text),source:source||"story",sig});
  m.memories = m.memories.sort((a,b)=>(a.turn-b.turn)).slice(-24);
  m.lastMemoryTurn = lkTurn();
}

function lk3ExtractGoalCue(name, sentence) {
  const s = lkLower(sentence);
  const first = lkLower(name.split(/\s+/)[0]);
  if (!s.includes(first) && !s.includes(lkLower(name))) return "";
  for (const verb of LK3_GOAL_VERBS) {
    if (s.includes(verb)) return lk3NormalizeSpace(sentence).slice(0,220);
  }
  return "";
}

function lk3UpdateMindFromText(name, text, source) {
  const m = lk3Mind(name);
  m.lastSeen = lkTurn();
  m.activationCount += 1;
  const rel = lkRelationship(name);
  const sentences = lk3Sentences(text).filter(x => {
    const low = lkLower(x);
    const first = lkLower(name.split(/\s+/)[0]);
    return low.includes(lkLower(name)) || low.includes(first);
  });
  for (const sentence of sentences.slice(-4)) {
    lk3Remember(name,sentence,source);
    const goalCue = lk3ExtractGoalCue(name,sentence);
    if (goalCue && !lkIncludesAny(goalCue,["you want","you need","you plan"])) {
      m.privatePlan = goalCue;
      m.lastPlanTurn = lkTurn();
    }
  }
  const local = lkLocalWindow(text,name,360);
  if (lk3CueHit(local,LK3_EMOTION_TERMS.angry)) m.mood="angry";
  else if (lk3CueHit(local,LK3_EMOTION_TERMS.afraid)) m.mood="afraid";
  else if (lk3CueHit(local,LK3_EMOTION_TERMS.hurt)) m.mood="hurt";
  else if (lk3CueHit(local,LK3_EMOTION_TERMS.warm)) m.mood="warm";
  else if (lk3CueHit(local,LK3_EMOTION_TERMS.jealous)) m.mood="jealous";
  else if (lk3CueHit(local,LK3_EMOTION_TERMS.confident)) m.mood="confident";
  else if (lk3CueHit(local,LK3_EMOTION_TERMS.guarded)) m.mood="guarded";
  const pressure = lkInit().pressure;
  m.stress = lkClamp(Math.round((pressure.familyStrain+pressure.rivalPressure+pressure.legalScrutiny)/9 + rel.fear/5 + rel.suspicion/8),0,100);
  m.confidence = lkClamp(55 + rel.respect/5 - rel.fear/5 - m.stress/10,0,100);
  m.riskTolerance = lkClamp(35 + rel.rivalry/5 + rel.resentment/6 - rel.fear/7,5,90);
  if (rel.affection >= 65 && rel.trust >= 55) m.stance="personally warm";
  else if (rel.resentment >= 65) m.stance="resentful";
  else if (rel.suspicion >= 65) m.stance="suspicious";
  else if (rel.fear >= 65) m.stance="fearful-cautious";
  else if (rel.rivalry >= 60) m.stance="competitive";
  else if (rel.respect >= 65) m.stance="respectful";
  else if (rel.trust >= 60) m.stance="open";
  else m.stance="guarded-neutral";
}

function lk3ActiveNames(text, source) {
  const active=[];
  const sentences=lk3Sentences(text);
  for(const sentence of sentences) {
    const clauses=sentence.split(/\s+(?:but|while|whereas|although|however|and then)\s+|[;—]/i).map(lk3NormalizeSpace).filter(Boolean);
    for(const clause of clauses.length?clauses:[sentence]) {
      const names=lkMentioned(clause);
      if(!names.length) continue;
      if(names.length===1) { active.push(names[0]); continue; }
      const ordered=names.map(n=>({n,p:lkLower(clause).indexOf(lkLower(n))})).filter(x=>x.p>=0).sort((a,b)=>a.p-b.p);
      // The first named person in a multi-NPC clause is usually the acting/observed subject.
      // For player input it is usually the direct person the player is addressing or acting on.
      if(ordered[0]) active.push(ordered[0].n);
      // Explicit information recipients are active participants too.
      active.push(...lk3KnowledgeRecipients(clause));
      // A direct continuity event makes the affected person active even when another name
      // appears earlier in the sentence (e.g. "Michael watches as Daniel is arrested").
      for(const n of names) if(lk3DetectStatusForName(clause,n)) active.push(n);
    }
  }
  return lkUnique(active);
}

function lk3ScanMinds(text, source) {
  const w = lk3GetW();
  if (!w.config.innerLives) return [];
  const names = lk3ActiveNames(text,source).slice(0,8);
  const sentences=lk3Sentences(text);
  for (const n of names) {
    const relevant=sentences.filter(sentence=>lk3ActiveNames(sentence,source).includes(n)).join(" ") || text;
    lk3UpdateMindFromText(n,relevant,source);
  }
  return names;
}

function lk3MindDirective(recentText) {
  const w = lk3GetW();
  if (!w.config.innerLives) return "";
  const names = lkMentioned(recentText).slice(-3);
  if (!names.length) return "";
  const lines=[];
  for (const name of names) {
    const m=lk3Mind(name), r=lkRelationship(name);
    const memories=(m.memories||[]).slice().sort((a,b)=>(b.salience-a.salience)||(b.turn-a.turn)).slice(0,2).map(x=>x.text.slice(0,120));
    const facts=(w.knowledge[name]||[]).slice(-2).map(x=>x.fact.slice(0,110));
    lines.push(`${name}: private goal=${m.coreGoal}; current plan=${m.privatePlan}; stance=${m.stance}; mood=${m.mood}; pressure=${m.pressurePoint || "none stated"}; remembers=${memories.join(" / ") || "no salient new event"}; known facts=${facts.join(" / ") || "only scene-available knowledge"}; rel cues T${r.trust} L${r.loyalty} Res${r.resentment} S${r.suspicion} A${r.affection} At${r.attraction} Riv${r.rivalry}.`);
  }
  return `INNER LIVES — PRIVATE BEHAVIOURAL GUIDANCE. Do not narrate these as omniscient thoughts or guaranteed truth. Let them shape choices, omissions, tone and initiative only:\n${lines.join("\n")}`;
}

function lk3AddKnowledge(name, fact, source) {
  const w=lk3GetW();
  if (!w.knowledge[name]) w.knowledge[name]=[];
  const clean=lk3NormalizeSpace(fact).slice(0,240);
  if (!clean) return;
  const sig=lkHash(name+"|"+clean);
  if (w.knowledge[name].some(x=>x.sig===sig)) return;
  w.knowledge[name].push({turn:lkTurn(),fact:clean,source:source||"story",sig});
  w.knowledge[name]=w.knowledge[name].slice(-18);
  w.runtime.factsLearned += 1;
}

function lk3KnowledgeRecipients(sentence) {
  const low=lkLower(sentence);
  const names=lkMentioned(sentence);
  const recipients=[];
  for(const verb of LK3_KNOWLEDGE_VERBS) {
    let pos=low.indexOf(verb);
    while(pos>=0) {
      const afterStart=pos+verb.length;
      const tail=sentence.slice(afterStart,afterStart+170);
      const tailLow=lkLower(tail);
      // If the explicit recipient is the player, do not accidentally treat a name in the
      // content of the message as the recipient (e.g. "Rebecca tells you Daniel lied").
      const firstNamePos=names.map(n=>({n,p:tailLow.search(new RegExp(`\\b${lk3NameRef(n)}\\b`,"i"))})).filter(x=>x.p>=0).sort((a,b)=>a.p-b.p)[0];
      const playerPos=tailLow.search(/\b(?:you|me|us)\b/);
      if(!(playerPos>=0 && (!firstNamePos || playerPos<firstNamePos.p))) {
        if(firstNamePos) {
          recipients.push(firstNamePos.n);
          // Support "tell Michael and Susan ..." without treating later content names as recipients.
          const rest=tailLow.slice(firstNamePos.p + firstNamePos.n.length, firstNamePos.p + firstNamePos.n.length + 70);
          if(/^\s*(?:,|and|&)\s*/i.test(rest)) {
            const second=names.map(n=>({n,p:tailLow.indexOf(lkLower(n),firstNamePos.p+firstNamePos.n.length)})).filter(x=>x.p>=0 && x.p-firstNamePos.p<90).sort((a,b)=>a.p-b.p)[0];
            if(second) recipients.push(second.n);
          }
        }
      }
      pos=low.indexOf(verb,pos+verb.length);
    }
  }
  return lkUnique(recipients);
}

function lk3KnowledgeScan(text, source) {
  const sentences=lk3Sentences(text);
  for (const sentence of sentences) {
    const low=lkLower(sentence);
    if (!LK3_KNOWLEDGE_VERBS.some(v=>low.includes(v))) continue;
    const recipients=lk3KnowledgeRecipients(sentence);
    for (const n of recipients) lk3AddKnowledge(n,sentence,source==="input"?"player explicitly communicated this":source);
  }
}

function lk3DetectStatusForName(text,name) {
  const ref=lk3NameRef(name);
  const t=lk3NormalizeSpace(text);
  const neg=new RegExp(`\\b${ref}\\b[^.!?]{0,45}\\b(?:is not|isn't|was not|wasn't|has not been|hasn't been|did not|didn't)\\b[^.!?]{0,25}\\b(?:dead|killed|arrested|charged|missing|injured|wounded)\\b`,"i");
  if(neg.test(t)) return "";
  const checks=[
    ["dead",[
      new RegExp(`\\b${ref}\\b\\s+(?:is|was|has been)\\s+(?:dead|killed)\\b`,"i"),
      new RegExp(`\\b${ref}\\b\\s+(?:dies|died)\\b`,"i"),
      new RegExp(`\\b(?:kills|killed)\\s+${ref}\\b`,"i")
    ]],
    ["arrested",[
      new RegExp(`\\b${ref}\\b\\s+(?:is|was|has been)\\s+(?:arrested|charged|detained|taken into custody)\\b`,"i"),
      new RegExp(`\\b(?:arrests|arrested|charges|charged|detains|detained)\\s+${ref}\\b`,"i")
    ]],
    ["missing",[
      new RegExp(`\\b${ref}\\b\\s+(?:is|was|has been)\\s+missing\\b`,"i"),
      new RegExp(`\\b${ref}\\b\\s+(?:has disappeared|disappeared|cannot be found|can't be found|has not been seen|hasn't been seen)\\b`,"i")
    ]],
    ["injured",[
      new RegExp(`\\b${ref}\\b\\s+(?:is|was|has been)\\s+(?:injured|wounded|hospitalised|hospitalized|bleeding)\\b`,"i"),
      new RegExp(`\\b${ref}\\b[^.!?]{0,35}\\b(?:has|suffers|suffered)\\s+(?:a\\s+)?broken\\b`,"i"),
      new RegExp(`\\b(?:shoots|shot|stabs|stabbed|wounds|wounded|injures|injured)\\s+${ref}\\b`,"i")
    ]],
    ["active",[
      new RegExp(`\\b${ref}\\b\\s+(?:is|was)\\s+(?:released|freed|discharged from hospital)\\b`,"i"),
      new RegExp(`\\b${ref}\\b\\s+returns home from hospital\\b`,"i"),
      new RegExp(`\\b${ref}(?:'s|’s)\\s+(?:charges|case)\\s+(?:are|is)\\s+dropped\\b`,"i"),
      new RegExp(`\\b(?:releases|released|frees|freed)\\s+${ref}\\b`,"i")
    ]]
  ];
  for(const [status,rxs] of checks) if(rxs.some(rx=>rx.test(t))) return status;
  return "";
}

function lk3StatusScan(text, source) {
  const w=lk3GetW();
  const names=lkMentioned(text).slice(0,8);
  for (const name of names) {
    const status=lk3DetectStatusForName(text,name);
    if (!status) continue;
    const prev=w.statuses[name]||{state:"active",turn:0};
    if (prev.state==="dead" && status!=="dead") continue;
    if (prev.state===status && prev.turn===lkTurn()) continue;
    w.statuses[name]={state:status,turn:lkTurn(),source};
    w.statusEvents.push({name,state:status,turn:lkTurn(),source});
    w.statusEvents=w.statusEvents.slice(-120);
    w.runtime.statusChanges += 1;
    lkPushTimeline({turn:lkTurn(),type:"status",name,status,source});
  }
}

function lk3ContinuityDirective(recentText) {
  const w=lk3GetW();
  const names=lkMentioned(recentText).slice(0,4);
  const rows=[];
  for (const n of names) {
    const s=w.statuses[n];
    if (s && s.state && s.state!=="active") rows.push(`${n}=${s.state} since turn ${s.turn}`);
  }
  return rows.length ? `CONTINUITY LOCK: ${rows.join("; ")}. Do not casually erase these states; changes require explicit plausible story events.` : "";
}

function lk3SceneClass(text) {
  const s=lkLower(text), scores={};
  for (const k of Object.keys(LK3_SCENE_TERMS)) scores[k]=LK3_SCENE_TERMS[k].filter(x=>s.includes(x)).length;
  return Object.keys(scores).sort((a,b)=>scores[b]-scores[a])[0] || "general";
}

function lk3WorldPulse(turn) {
  const w=lk3GetW();
  if (!w.config.livingWorld || turn===w.lastContextTickV3) return;
  const intensity=lkClamp(w.config.intensity,1,3);
  const keys=Object.keys(w.pressure);
  const primary=keys[lkHash(`v3-world-${turn}`)%keys.length];
  const direction=(lkHash(`v3-dir-${turn}`)%9===0)?-1:1;
  w.pressure[primary]=lkClamp(w.pressure[primary]+direction*intensity,0,100);
  if (turn%11===0) w.pressure.internalCompetition=lkClamp(w.pressure.internalCompetition+intensity,0,100);
  if (turn%17===0) w.pressure.businessStress=lkClamp(w.pressure.businessStress+1,0,100);
  if (turn%23===0) w.pressure.publicExposure=lkClamp(w.pressure.publicExposure+1,0,100);
}

function lk3GoalPulse(turn) {
  const w=lk3GetW();
  if (!w.config.npcGoals) return;
  const names=Object.keys(w.goals||{});
  if (!names.length) return;
  const count=Math.min(1+w.config.intensity,3);
  for (let i=0;i<count;i++) {
    const n=names[lkHash(`v3-goal-${turn}-${i}`)%names.length];
    const g=w.goals[n];
    if (!g) continue;
    const seenRecently=(w.recentMentions||[]).includes(n);
    const delta=seenRecently?0:1;
    g.momentum=lkClamp((g.momentum||0)+delta,0,100);
    g.lastAdvance=turn;
  }
}

function lk3TwistStageFor(tw, turn) {
  const w=lk3GetW();
  const pace=lkClamp(w.config.twistPace,3,20);
  const age=Math.max(0,turn-(tw.created||turn));
  if (tw.stage==="fallout" && age>=pace*5) return "resolved";
  if (tw.stage==="resolved") return "resolved";
  if (age>=pace*4) return "ripe";
  if (age>=pace*3) return "complicate";
  if (age>=pace*2) return "grow";
  return "seed";
}

function lk3TwistPulse(turn,recentText) {
  const w=lk3GetW();
  if (!w.config.twists) return;
  w.config.maxActiveTwists=w.config.maxTwists;
  w.config.twistSeedSpacing=w.config.twistPace;
  w.config.twistGrowAfter=w.config.twistPace;
  w.config.twistComplicateAfter=w.config.twistPace;
  w.config.twistRipeAfter=w.config.twistPace;
  w.config.twistFalloutTurns=w.config.twistPace;
  lkMaybeSeedTwist(turn,recentText);
  for (const tw of w.twists||[]) {
    if (tw.stage==="resolved") continue;
    if (tw.stage==="fallout") {
      if (turn-(tw.stageTurn||turn) >= w.config.twistPace) lkArchiveTwist(tw,"fallout complete");
      continue;
    }
    const next=lk3TwistStageFor(tw,turn);
    if (next!==tw.stage) { tw.stage=next; tw.stageTurn=turn; }
  }
}

function lk3TwistDirective(turn) {
  const w=lk3GetW();
  if (!w.config.twists) return "";
  const active=(w.twists||[]).filter(t=>t.stage!=="resolved");
  if (!active.length) return "";
  const ripe=active.filter(t=>t.stage==="ripe");
  const pool=ripe.length?ripe:active;
  const tw=pool[lkHash(`directive-${turn}`)%pool.length];
  if (!tw) return "";
  if (tw.stage==="seed") return `TWIST ${tw.id} [hidden]: Around ${tw.focus}, plant one mundane discrepancy consistent with this eventual truth: ${tw.truth} Do NOT explain it, label it suspicious, or reveal the truth.`;
  if (tw.stage==="grow") return `TWIST ${tw.id} [hidden]: Around ${tw.focus}, add one independent clue or consequence consistent with: ${tw.truth} It may have an innocent-looking explanation. No confession.`;
  if (tw.stage==="complicate") return `TWIST ${tw.id} [hidden]: Around ${tw.focus}, introduce a credible competing interpretation or conflicting incentive while preserving prior facts. Underlying truth: ${tw.truth}`;
  if (tw.stage==="ripe") return `TWIST ${tw.id} [hidden, ripe]: Underlying truth: ${tw.truth} A reveal is permitted ONLY if the current scene has a believable evidence/source chain. Otherwise deepen it. Reveal must reinterpret, not retcon.`;
  if (tw.stage==="fallout") return `TWIST ${tw.id} fallout: prioritise practical, relational and political consequences of the reveal around ${tw.focus}; do not immediately replace it with another huge twist.`;
  return "";
}

function lk3MatureDirective(recentText) {
  const w=lk3GetW();
  if (!w.config.matureTone) return "";
  if (w.profile && w.profile.isAdult===false) return "AGE SAFETY: the player profile is under 18. Do not include sexual content involving the player. Keep any adult sexual material away from minors.";
  const scene=lk3SceneClass(recentText);
  if (scene==="violence") return "18+ TONE: violence may be graphically physical and consequential; preserve injuries, witnesses, evidence and aftermath. Do not turn it into procedural criminal instruction.";
  if (scene==="romance") return "18+ TONE: adult attraction/intimacy may develop naturally and may be described directly when consensual, without pornographic anatomical detail. Keep consent separate from fear, intoxication, employment or criminal leverage. Sex does not automatically equal love, trust or loyalty.";
  return "18+ TONE: strong language and adult subject matter are permitted when character-appropriate; do not force sex or violence into unrelated scenes.";
}

function lk3RelationshipDirective(recentText) {
  const names=lkMentioned(recentText).slice(-3);
  if (!names.length) return "";
  const rows=[];
  for (const n of names) {
    const r=lkRelationship(n);
    rows.push(`${n}: trust=${r.trust}, loyalty=${r.loyalty}, respect=${r.respect}, fear=${r.fear}, resentment=${r.resentment}, affection=${r.affection}, attraction=${r.attraction}, suspicion=${r.suspicion}, obligation=${r.obligation}, rivalry=${r.rivalry}, jealousy=${r.jealousy}, dependence=${r.dependence}`);
  }
  return `RELATIONSHIPS [hidden numeric guidance; never quote numbers]: ${rows.join(" | ")}. Express through behaviour. Dimensions are independent.`;
}

function lk3GoalDirective(turn,recentText) {
  const w=lk3GetW();
  if (!w.config.npcGoals) return "";
  const sceneNames=new Set(lkMentioned(recentText));
  const pool=Object.keys(w.goals||{}).map(n=>({name:n,g:w.goals[n]})).filter(x=>!sceneNames.has(x.name));
  pool.sort((a,b)=>(b.g.momentum||0)-(a.g.momentum||0));
  const top=pool[0];
  if (!top || (top.g.momentum||0)<10) return "";
  return `NPC AUTONOMY: if a believable channel exists, let ONE offscreen consequence of ${top.name}'s goal surface: ${top.g.summary}. Pressure point: ${top.g.pressurePoint || "none stated"}. Do not teleport ${top.name} into the scene or expose private motives without evidence.`;
}

function lk3WorldDirective() {
  const w=lk3GetW();
  if (!w.config.livingWorld) return "";
  const p=w.pressure;
  const ranked=[
    ["family strain",p.familyStrain],["rival pressure",p.rivalPressure],["law scrutiny",p.legalScrutiny],
    ["business stress",p.businessStress],["public exposure",p.publicExposure],["internal competition",p.internalCompetition]
  ].sort((a,b)=>b[1]-a[1]);
  const top=ranked[0];
  return `LIVING WORLD: highest current pressure=${top[0]} (${top[1]}/100). If relevant, advance ONE concrete consequence through a plausible source. The world may also improve or remain quiet; do not manufacture disaster every turn.`;
}

function lk3PromiseDirective(recentText) {
  const w=lk3GetW();
  const names=lkMentioned(recentText);
  const open=(w.promises||[]).filter(p=>p.status==="open" && (!names.length || p.people.some(n=>names.includes(n))));
  if (!open.length) return "";
  const p=open[open.length-1];
  return `OPEN OBLIGATION: ${p.id}, turn ${p.turn}, people=${p.people.join(", ")}, record=${p.text.slice(0,170)}. Remember it without forcing immediate collection.`;
}

function lk3FrontMemory(recentText) {
  const w=lk3GetW();
  const turn=lkTurn();
  const lines=[
    `[LONG KNIVES ENGINE v${LK_VERSION} • turn ${turn}. Hidden guidance. Never mention engine, config, numeric state or "Inner Lives" in prose.]`,
    `PLAYER AGENCY: only the user chooses the protagonist's intentional speech, thoughts, consent and decisions. Character knowledge is local.`,
    lk3ProfileDirective(),
    lk3ContinuityDirective(recentText),
    lk3RelationshipDirective(recentText),
    lk3MindDirective(recentText),
    lk3PromiseDirective(recentText),
    lk3GoalDirective(turn,recentText),
    lk3WorldDirective(),
    lk3TwistDirective(turn),
    lk3MatureDirective(recentText),
    `PACING: continue ONE primary beat with new material. Preserve quiet life, business, relationships and consequences alongside crime. Small clues may remain small.`
  ].filter(Boolean);
  return lines.join("\n").slice(0,w.config.frontMemoryMax);
}

function lk3ScanText(text, source) {
  const w=lk3GetW();
  if (!lk3PreparePhase(source,text)) return [];
  const touched=lk3RelationshipScan(text,source);
  const names=lk3ScanMinds(text,source);
  lk3KnowledgeScan(text,source);
  lk3StatusScan(text,source);
  w.recentMentions=lkUnique((w.recentMentions||[]).concat(names)).slice(-24);
  lkPressureFromText(text);
  lkUpdatePlayerFromText(text,source);
  return lkUnique(touched.concat(names));
}

function lk3ContextCycle(text) {
  const w=lk3GetW();
  lk3ReconcileTurn();
  const turn=lkTurn();
  const recent=lkRecentHistory(w.config.memoryDepth) + "\n" + lkText(text).slice(-2500);
  if (turn!==w.lastContextTickV3) {
    const goalMomentum={}; for (const n of Object.keys(w.goals||{})) goalMomentum[n]=w.goals[n].momentum||0;
    w.contextSnapshots[turn]={pressure:JSON.parse(JSON.stringify(w.pressure)),goalMomentum,twists:JSON.parse(JSON.stringify(w.twists||[])),twistArchive:JSON.parse(JSON.stringify(w.twistArchive||[])),twistsResolved:w.counters&&w.counters.twistsResolved||0};
    for (const k of Object.keys(w.contextSnapshots)) if(Number(k)<turn-60) delete w.contextSnapshots[k];
    lk3WorldPulse(turn);
    lk3GoalPulse(turn);
    lk3TwistPulse(turn,recent);
    w.lastContextTickV3=turn;
  }
  state.memory=state.memory||{};
  state.memory.frontMemory=lk3FrontMemory(recent);
  if (w.config.statusCard) lk3UpdateStatusCard();
  return state.memory.frontMemory;
}

function lk3MindCommand(arg) {
  const w=lk3GetW();
  const q=lkText(arg).trim();
  if (!q) {
    const rows=Object.keys(w.minds||{}).map(n=>w.minds[n]).sort((a,b)=>(b.lastSeen||0)-(a.lastSeen||0)).slice(0,12);
    return "LONG KNIVES INNER LIVES (spoiler-safe)\n"+(rows.length?rows.map(m=>`${m.name}: ${m.stance}; mood ${m.mood}; last active ${m.lastSeen}`).join("\n"):"No NPC minds activated yet.");
  }
  const roster=lkBuildRoster();
  const match=roster.find(r=>lkLower(r.name)===lkLower(q)) || roster.find(r=>lkLower(r.name).includes(lkLower(q)));
  if (!match) return `LONG KNIVES INNER LIVES\nNo character match for: ${q}`;
  const m=lk3Mind(match.name), r=lkRelationship(match.name);
  const memories=(m.memories||[]).slice(-5).map(x=>`turn ${x.turn}: ${x.tag} — ${x.text.slice(0,135)}`).join("\n")||"No salient remembered events yet.";
  return `LONG KNIVES INNER LIVES — ${match.name}\nExterior stance: ${m.stance}; mood: ${m.mood}; stress: ${m.stress}; confidence: ${Math.round(m.confidence)}\nRelationship: trust ${r.trust}, loyalty ${r.loyalty}, respect ${r.respect}, fear ${r.fear}, resentment ${r.resentment}, affection ${r.affection}, attraction ${r.attraction}, suspicion ${r.suspicion}, rivalry ${r.rivalry}, jealousy ${r.jealousy}, dependence ${r.dependence}\nRecent remembered events:\n${memories}\nPrivate goal/plan is deliberately hidden unless debug=true.`+(w.config.debug?`\nDEBUG PRIVATE goal=${m.coreGoal}; plan=${m.privatePlan}; pressure=${m.pressurePoint}`:"");
}

function lk3ProfileCommand() {
  const p=lk3GetW().profile;
  return `LONG KNIVES PLAYER PROFILE\nName: ${p.name}\nAge: ${p.age}\nRole: ${p.role}\nExpertise: ${p.expertise||"not provided"}\nDetected domains: ${(p.skillTags||[]).join(", ")||"none"}\nElite/best-in-story claim: ${p.eliteClaim?"yes":"no"}\nLimits: ${p.limits||"not provided"}\nAmbition: ${p.ambition||"not provided"}`;
}

function lk3KnowledgeCommand(arg) {
  const w=lk3GetW(), q=lkText(arg).trim();
  if (!q) return "LONG KNIVES KNOWLEDGE\nUse /knowledge NAME to inspect what the engine has explicitly recorded that an NPC was told/witnessed. This is a continuity aid, not omniscient truth.";
  const roster=lkBuildRoster();
  const match=roster.find(r=>lkLower(r.name)===lkLower(q)) || roster.find(r=>lkLower(r.name).includes(lkLower(q)));
  if (!match) return `LONG KNIVES KNOWLEDGE\nNo character match for: ${q}`;
  const facts=(w.knowledge[match.name]||[]).slice(-10);
  return `LONG KNIVES KNOWLEDGE — ${match.name}\n`+(facts.length?facts.map(x=>`turn ${x.turn}: ${x.fact}`).join("\n"):"No explicit transmitted facts recorded yet.");
}

function lk3PersistConfigKey(key,value) {
  const w=lk3GetW();
  if (typeof storyCards==="undefined" || !Array.isArray(storyCards) || typeof updateStoryCard!=="function") {
    w.configOverrides[key]=value;
    return false;
  }
  const ix=storyCards.findIndex(c=>lkCardKeys(c).includes("%LONG_KNIVES_CONFIG%"));
  if (ix<0) { w.configOverrides[key]=value; return false; }
  const card=storyCards[ix];
  let entry=lkCardEntry(card);
  const rx=new RegExp(`(\\b${lk3EscapeRegExp(key)}\\s*=\\s*)[^|]+`,"i");
  if (rx.test(entry)) entry=entry.replace(rx,`$1${value} `);
  else entry=entry.replace(/\s*$/,` | ${key}=${value}`);
  try {
    updateStoryCard(ix,lkCardKeys(card),entry,lkCardType(card)||"custom");
    delete w.configOverrides[key];
    return true;
  } catch(e) {
    w.configOverrides[key]=value;
    lkSafeLog("config card update failed: "+e);
    return false;
  }
}

function lk3ConfigSet(key,val) {
  const w=lk3GetW();
  const boolKeys=["enabled","relationships","innerLives","livingWorld","npcGoals","twists","profileAuthority","matureTone","statusCard","debug"];
  const numKeys=["intensity","updateEvery","twistPace","maxTwists","memoryDepth","frontMemoryMax"];
  if (boolKeys.includes(key)) w.config[key]=lkBool(val,w.config[key]);
  else if (numKeys.includes(key)) w.config[key]=lkNum(val,w.config[key]);
  else return `Unknown config key: ${key}`;
  w.config.intensity=lkClamp(w.config.intensity,1,3);
  w.config.updateEvery=lkClamp(w.config.updateEvery,1,50);
  w.config.twistPace=lkClamp(w.config.twistPace,3,20);
  w.config.maxTwists=lkClamp(w.config.maxTwists,1,8);
  w.config.memoryDepth=lkClamp(w.config.memoryDepth,4,30);
  w.config.frontMemoryMax=lkClamp(w.config.frontMemoryMax,1200,5200);
  const finalValue=w.config[key];
  const persisted=lk3PersistConfigKey(key,finalValue);
  if (!persisted) w.configOverrides[key]=finalValue;
  return `LONG KNIVES CONFIG\n${key}=${finalValue}${persisted?" (saved to config card)":" (runtime override)"}`;
}

function lk3ConfigCommand() {
  const c=lk3GetW().config;
  const keys=["enabled","relationships","innerLives","livingWorld","npcGoals","twists","profileAuthority","matureTone","statusCard","intensity","updateEvery","twistPace","maxTwists","memoryDepth","frontMemoryMax","debug"];
  return "LONG KNIVES CONFIG\n"+keys.map(k=>`${k}=${c[k]}`).join("\n")+"\nUse /config set KEY VALUE. The Story Card Notes explain each option.";
}

function lk3Status() {
  const w=lk3GetW();
  const active=(w.twists||[]).filter(t=>t.stage!=="resolved");
  const mindCount=Object.keys(w.minds||{}).length;
  const statusCount=Object.keys(w.statuses||{}).filter(n=>w.statuses[n].state!=="active").length;
  return `LONG KNIVES ENGINE v${LK_VERSION} • action ${lkTurn()}\nPlayer: ${w.profile.name}; ${lkStanding()}; influence ${w.player.influence}; expertise ${(w.profile.skillTags||[]).join(", ")||"profile-defined"}\nPressure: ${lkPressureSummary()}\nRelationships tracked: ${Object.keys(w.relationships||{}).length}; INNER LIVES active: ${mindCount}; continuity statuses: ${statusCount}\nTwists: ${active.length} active (${active.slice(0,5).map(t=>`${t.focus}:${t.stage}`).join(" | ")||"none"})\nPromises/debts: ${(w.promises||[]).filter(p=>p.status==="open").length}; NPC goals: ${Object.keys(w.goals||{}).length}\nRuntime: scans ${w.runtime.scans}, retries handled ${w.runtime.retries}, rewinds handled ${w.runtime.rewinds}`;
}

function lk3UpdateStatusCard(force) {
  const w=lk3GetW();
  if (!w.config.statusCard || typeof storyCards==="undefined" || !Array.isArray(storyCards) || typeof updateStoryCard!=="function") return false;
  const turn=lkTurn();
  if(!force && Number.isFinite(w.lastStatusCardUpdateV3) && turn-w.lastStatusCardUpdateV3 < w.config.updateEvery) return false;
  const ix=storyCards.findIndex(c=>lkCardKeys(c).includes("%LONG_KNIVES_STATUS%"));
  if (ix<0) return false;
  const entry=lk3Status().replace(/\n/g," | ").slice(0,930);
  try { updateStoryCard(ix,"%LONG_KNIVES_STATUS%",entry,"custom"); w.lastStatusCardUpdateV3=turn; return true; }
  catch(e) { lkSafeLog("v3 status card update failed: "+e); return false; }
}

function lk3Command(text) {
  const raw=lkText(text).trim();
  if (!raw.startsWith("/")) return null;
  if (/^\/status\s*[.!?]?$/.test(raw)) return lk3Status();
  if (/^\/profile\s*[.!?]?$/.test(raw)) return lk3ProfileCommand();
  if (/^\/threads\s*[.!?]?$/.test(raw)) return lkThreadsCommand();
  if (/^\/promises\s*[.!?]?$/.test(raw)) return lkPromisesCommand();
  if (/^\/goals\s*[.!?]?$/.test(raw)) return lkGoalsCommand();
  if (/^\/world\s*[.!?]?$/.test(raw)) return lkWorldCommand();
  if (/^\/config\s*[.!?]?$/.test(raw)) return lk3ConfigCommand();
  if (/^\/help\s*[.!?]?$/.test(raw)) return "LONG KNIVES COMMANDS\n/status — engine dashboard\n/profile — authoritative player profile\n/relations [NAME] — relationship state\n/mind [NAME] — spoiler-safe INNER LIVES view\n/knowledge NAME — explicit knowledge ledger\n/threads — world + twist stages\n/promises — open promises/debts\n/goals — NPC goal momentum\n/world — pressure\n/config — settings\n/config set KEY VALUE — change setting\n/debug on|off — debug mode\n/help — this list";
  let m=raw.match(/^\/relations(?:\s+(.+?))?\s*[.!?]?$/i); if(m) return lkRelationsCommand(m[1]||"");
  m=raw.match(/^\/mind(?:\s+(.+?))?\s*[.!?]?$/i); if(m) return lk3MindCommand(m[1]||"");
  m=raw.match(/^\/knowledge\s+(.+?)\s*[.!?]?$/i); if(m) return lk3KnowledgeCommand(m[1]||"");
  m=raw.match(/^\/debug\s+(on|off)\s*[.!?]?$/i); if(m) { const w=lk3GetW(); w.config.debug=m[1].toLowerCase()==="on"; return `LONG KNIVES debug ${w.config.debug?"ON":"OFF"}.`; }
  m=raw.match(/^\/config\s+set\s+([A-Za-z][A-Za-z0-9]*)\s+(.+?)\s*[.!?]?$/i); if(m) return lk3ConfigSet(m[1],m[2]);
  return null;
}

function lk3Input(text) {
  try {
    const w=lk3GetW();
    lk3ReconcileTurn();
    if (!w.config.enabled) return {text};
    const command=lk3Command(text);
    if (command) {
      w.pendingCommandV3=command;
      return {text:lkText(text)+"\n[Engine command. Do not advance the story; a script will replace the model output.]"};
    }
    lk3ScanText(text,"input");
    return {text};
  } catch(e) {
    try { const w=state.longKnives||{}; if(w.runtime) w.runtime.errors++; if(typeof log==="function") log("LONG KNIVES v3 input error: "+e); } catch(_) {}
    return {text};
  }
}

function lk3Context(text) {
  try {
    const w=lk3GetW();
    if (!w.config.enabled) return {text};
    lk3ContextCycle(text);
    return {text};
  } catch(e) {
    try { const w=state.longKnives||{}; if(w.runtime) w.runtime.errors++; if(typeof log==="function") log("LONG KNIVES v3 context error: "+e); } catch(_) {}
    return {text};
  }
}

function lk3Output(text) {
  try {
    const w=lk3GetW();
    if (!w.config.enabled) return {text};
    if (w.pendingCommandV3) {
      const result=w.pendingCommandV3;
      delete w.pendingCommandV3;
      lk3UpdateStatusCard(true);
      return {text:result};
    }
    lk3ScanText(text,"output");
    lkResolveTwistFromOutput(text);
    lk3UpdateStatusCard();
    return {text};
  } catch(e) {
    try { const w=state.longKnives||{}; if(w.runtime) w.runtime.errors++; if(typeof log==="function") log("LONG KNIVES v3 output error: "+e); } catch(_) {}
    return {text};
  }
}

