function lk3AliasCategoryHits(text) {
  const s=lkLower(text);
  const found=[];
  // The aliases are deliberately broad fallback vocabulary. Exact cue tables above carry most weight.
  // We token-test the meaningful verb fragment rather than requiring placeholder words like "someone".
  for (const row of LK3_SOCIAL_EVENT_ALIASES) {
    const bits=row.text.split(" someone ");
    const left=bits[0].replace(/^(the player|you|michael|susan|andrew|rebecca|daniel|peter|martin|joanne|darren)\s+/i,"");
    if (left.length>=4 && s.includes(lkLower(left))) found.push(row.cat);
    if (found.length>=6) break;
  }
  return lkUnique(found);
}

function lk3Diagnostics() {
  const w=lk3GetW();
  return {
    version:w.version,
    turn:lkTurn(),
    relationships:Object.keys(w.relationships||{}).length,
    minds:Object.keys(w.minds||{}).length,
    knowledgeCharacters:Object.keys(w.knowledge||{}).length,
    goals:Object.keys(w.goals||{}).length,
    activeTwists:(w.twists||[]).filter(t=>t.stage!=="resolved").length,
    archivedTwists:(w.twistArchive||[]).length,
    promises:(w.promises||[]).length,
    profile:w.profile,
    runtime:w.runtime,
    frontMemoryLength:state.memory&&state.memory.frontMemory?state.memory.frontMemory.length:0
  };
}
